    void ruleIsStatelessAcrossInvocations() throws IOException {
        OFDReader reader = readerOf(entity("Page_1", annot(60)));

        List<ArchiveViolation> first = check(reader);
        List<ArchiveViolation> second = check(reader);

        assertEquals(descriptions(first), descriptions(second));
        assertEquals(2, first.size());
        assertNotSame(first, second, "每次调用应返回新的列表实例");
        assertNotSame(first.get(0), second.get(0), "每次调用应创建新的违规项实例");
    }

    @Test
    @DisplayName("ofdDir 入参不影响检查结果")
    void ofdDirArgumentDoesNotAffectResult() throws IOException {
        OFDReader reader = readerOf(entity("Page_1", compliantAnnot(70), annot(71)));

        List<ArchiveViolation> withNull = rule.check(reader, null);
        OFDDir ofdDir = reader.getOFDDir();
        assertNotNull(ofdDir);
        List<ArchiveViolation> withOfdDir = rule.check(reader, ofdDir);

        assertEquals(2, withNull.size());
        assertEquals(descriptions(withNull), descriptions(withOfdDir));
        for (ArchiveViolation v : withOfdDir) {
            assertEquals(AnnotationRule.RULE_NAME, v.getRuleName());
            assertFalse(v.getDescription().isEmpty());
        }
    }
