package org.ofdrw.archive.check.rule;

import org.apache.commons.io.FileUtils;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.ofdrw.archive.check.ArchiveViolation;
import org.ofdrw.core.annotation.pageannot.Annot;
import org.ofdrw.core.annotation.pageannot.Appearance;
import org.ofdrw.core.basicStructure.pageObj.layer.block.CT_PageBlock;
import org.ofdrw.core.basicType.ST_Box;
import org.ofdrw.core.basicType.ST_ID;
import org.ofdrw.pkg.container.OFDDir;
import org.ofdrw.reader.OFDReader;
import org.ofdrw.reader.model.AnnotionEntity;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNotSame;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * {@link AnnotationRule} 的单元测试。
 * <p>
 * 覆盖：无注释数据、合规注释、ReadOnly/NoZoom/NoRotate 单项与组合不合规、
 * Appearance 中 PageBlock 嵌套（含多层嵌套）、缺失 ID、多页多注释、
 * 以及读取异常与脏数据导致的 ERROR 分支。
 */
class AnnotationRuleCheckTests {

    /** 测试过程中创建的临时工作目录，测试结束后删除 */
    private final List<Path> tempDirs = new ArrayList<>();

    private final AnnotationRule rule = new AnnotationRule();

    @AfterEach
    void cleanUp() throws IOException {
        for (Path dir : tempDirs) {
            FileUtils.deleteDirectory(dir.toFile());
        }
        tempDirs.clear();
    }

    // ------------------------------------------------------------------
    // 测试辅助
    // ------------------------------------------------------------------

    /**
     * 构造一个仅覆写 {@link OFDReader#getAnnotationEntities()} 的 Reader 替身。
     *
     * @param entities 需要返回的注释实体，可为 null
     * @param failure  若不为 null，则读取注释实体时抛出该异常
     */
    private OFDReader readerStub(final List<AnnotionEntity> entities, final RuntimeException failure) throws IOException {
        Path dir = Files.createTempDirectory("annotation-rule-test");
        tempDirs.add(dir);
        return new OFDReader(dir.toAbsolutePath().toString(), false) {
            @Override
            public List<AnnotionEntity> getAnnotationEntities() {
                if (failure != null) {
                    throw failure;
                }
                return entities;
            }

            @Override
            public void close() {
                // 临时目录由测试统一清理
            }
        };
    }

    private OFDReader readerOf(AnnotionEntity... entities) throws IOException {
        return readerStub(Arrays.asList(entities), null);
    }

    private static Annot annot(long id) {
        Annot annot = new Annot();
        annot.setID(new ST_ID(id));
        return annot;
    }

    /** 完全合规的注释：ReadOnly/NoZoom/NoRotate 均为 true，且无 Appearance */
    private static Annot compliantAnnot(long id) {
        Annot annot = annot(id);
        annot.setReadOnly(Boolean.TRUE);
        annot.setNoZoom(Boolean.TRUE);
        annot.setNoRotate(Boolean.TRUE);
        return annot;
    }

    private static Appearance appearance() {
        return new Appearance(new ST_Box(0, 0, 100, 100));
    }

    private static AnnotionEntity entity(String pageId, Annot... annots) {
        return new AnnotionEntity(pageId, Arrays.asList(annots));
    }

    private List<ArchiveViolation> check(OFDReader reader) {
        return rule.check(reader, null);
    }

    private static List<String> descriptions(List<ArchiveViolation> violations) {
        List<String> res = new ArrayList<>(violations.size());
        for (ArchiveViolation v : violations) {
            res.add(v.getDescription());
        }
        return res;
    }

    // ------------------------------------------------------------------
    // 无数据 / 合规场景
    // ------------------------------------------------------------------

    @Test
    @DisplayName("注释实体为 null 时返回空列表")
    void nullAnnotationEntitiesProducesNoViolations() throws IOException {
        OFDReader reader = readerStub(null, null);

        List<ArchiveViolation> violations = check(reader);

        assertNotNull(violations);
        assertTrue(violations.isEmpty());
    }

    @Test
    @DisplayName("注释实体为空集合时返回空列表")
    void emptyAnnotationEntitiesProducesNoViolations() throws IOException {
        OFDReader reader = readerStub(Collections.<AnnotionEntity>emptyList(), null);

        List<ArchiveViolation> violations = check(reader);

        assertNotNull(violations);
        assertTrue(violations.isEmpty());
    }

    @Test
    @DisplayName("页面中没有注释时返回空列表")
    void entityWithoutAnnotsProducesNoViolations() throws IOException {
        OFDReader reader = readerStub(
                Collections.singletonList(new AnnotionEntity("Page_3", Collections.<Annot>emptyList())), null);

        List<ArchiveViolation> violations = check(reader);

        assertTrue(violations.isEmpty());
    }

    @Test
    @DisplayName("ReadOnly/NoZoom/NoRotate 均为 true 且无 Appearance 的注释不产生违规项")
    void fullyCompliantAnnotProducesNoViolations() throws IOException {
        OFDReader reader = readerOf(entity("Page_1", compliantAnnot(10)));

        List<ArchiveViolation> violations = check(reader);

        assertTrue(violations.isEmpty(), "合规注释不应产生违规项，实际: " + descriptions(violations));
    }

    @Test
    @DisplayName("Appearance 存在但没有嵌套 PageBlock 时不产生违规项")
    void appearanceWithoutNestedPageBlockProducesNoViolations() throws IOException {
        Annot annot = compliantAnnot(11);
        annot.setAppearance(appearance());
        OFDReader reader = readerOf(entity("Page_1", annot));

        List<ArchiveViolation> violations = check(reader);

        assertTrue(violations.isEmpty(), "无嵌套 PageBlock 时不应产生违规项，实际: " + descriptions(violations));
    }

    // ------------------------------------------------------------------
    // ReadOnly / NoZoom / NoRotate
    // ------------------------------------------------------------------

    @Test
    @DisplayName("未显式设置的注释因 NoZoom/NoRotate 默认值为 false 产生 2 条 WARN")
    void defaultAnnotProducesTwoWarnings() throws IOException {
        OFDReader reader = readerOf(entity("Page_1", annot(12)));

        List<ArchiveViolation> violations = check(reader);

        assertEquals(2, violations.size(), "默认 NoZoom/NoRotate 为 false，应产生 2 条违规项，实际: "
                + descriptions(violations));
        for (ArchiveViolation v : violations) {
            assertEquals(AnnotationRule.RULE_NAME, v.getRuleName());
            assertEquals(ArchiveViolation.Severity.WARN, v.getSeverity());
            assertEquals("false", v.getActualValue());
            assertEquals("true", v.getExpectedValue());
            assertEquals("Annots/Annot_Page_1.xml", v.getLocation().getLoc());
        }
        assertTrue(descriptions(violations).get(0).contains("NoZoom"), "首条应为 NoZoom 检查");
        assertTrue(descriptions(violations).get(1).contains("NoRotate"), "次条应为 NoRotate 检查");
    }

    @Test
    @DisplayName("ReadOnly 为 false 时产生一条 WARN 违规项，且包含 ID 与位置信息")
    void readOnlyFalseProducesWarning() throws IOException {
        Annot annot = compliantAnnot(20);
        annot.setReadOnly(Boolean.FALSE);
        OFDReader reader = readerOf(entity("Page_7", annot));

        List<ArchiveViolation> violations = check(reader);

        assertEquals(1, violations.size(), "仅 ReadOnly 不合规时应有 1 条违规项，实际: " + descriptions(violations));
        ArchiveViolation v = violations.get(0);
        assertEquals(AnnotationRule.RULE_NAME, v.getRuleName());
        assertEquals(ArchiveViolation.Severity.WARN, v.getSeverity());
        assertTrue(v.getDescription().contains("ReadOnly"), "描述应包含 ReadOnly，实际: " + v.getDescription());
        assertTrue(v.getDescription().contains("ID=20"), "描述应包含注释 ID，实际: " + v.getDescription());
        assertEquals("false", v.getActualValue());
        assertEquals("true", v.getExpectedValue());
        assertNotNull(v.getLocation());
        assertEquals("Annots/Annot_Page_7.xml", v.getLocation().getLoc());
    }

    @Test
    @DisplayName("NoZoom 为 false 时产生一条 WARN 违规项")
    void noZoomFalseProducesWarning() throws IOException {
        Annot annot = compliantAnnot(21);
        annot.setNoZoom(Boolean.FALSE);
        OFDReader reader = readerOf(entity("Page_2", annot));

        List<ArchiveViolation> violations = check(reader);

        assertEquals(1, violations.size(), "仅 NoZoom 不合规时应有 1 条违规项，实际: " + descriptions(violations));
        ArchiveViolation v = violations.get(0);
        assertEquals(ArchiveViolation.Severity.WARN, v.getSeverity());
        assertTrue(v.getDescription().contains("NoZoom"), "描述应包含 NoZoom，实际: " + v.getDescription());
        assertTrue(!v.getDescription().contains("ReadOnly"), "不应混入 ReadOnly 检查");
        assertEquals("false", v.getActualValue());
        assertEquals("true", v.getExpectedValue());
        assertEquals("Annots/Annot_Page_2.xml", v.getLocation().getLoc());
    }

    @Test
    @DisplayName("NoRotate 为 false 时产生一条 WARN 违规项")
    void noRotateFalseProducesWarning() throws IOException {
        Annot annot = compliantAnnot(22);
        annot.setNoRotate(Boolean.FALSE);
        OFDReader reader = readerOf(entity("Page_2", annot));

        List<ArchiveViolation> violations = check(reader);

        assertEquals(1, violations.size(), "仅 NoRotate 不合规时应有 1 条违规项，实际: " + descriptions(violations));
        ArchiveViolation v = violations.get(0);
        assertEquals(ArchiveViolation.Severity.WARN, v.getSeverity());
        assertTrue(v.getDescription().contains("NoRotate"), "描述应包含 NoRotate，实际: " + v.getDescription());
        assertEquals("false", v.getActualValue());
        assertEquals("true", v.getExpectedValue());
    }

    @Test
    @DisplayName("三个布尔属性均不合规时按 ReadOnly/NoZoom/NoRotate 顺序产生 3 条 WARN")
    void allThreeFlagsFalseProducesThreeWarnings() throws IOException {
        Annot annot = annot(23);
        annot.setReadOnly(Boolean.FALSE);
        annot.setNoZoom(Boolean.FALSE);
        annot.setNoRotate(Boolean.FALSE);
        OFDReader reader = readerOf(entity("Page_9", annot));

        List<ArchiveViolation> violations = check(reader);

        assertEquals(3, violations.size(), "三个属性均不合规时应有 3 条违规项，实际: " + descriptions(violations));
        List<String> descs = descriptions(violations);
        assertTrue(descs.get(0).contains("ReadOnly"));
        assertTrue(descs.get(1).contains("NoZoom"));
        assertTrue(descs.get(2).contains("NoRotate"));
        for (ArchiveViolation v : violations) {
            assertEquals(ArchiveViolation.Severity.WARN, v.getSeverity());
            assertEquals("Annots/Annot_Page_9.xml", v.getLocation().getLoc());
            assertEquals("false", v.getActualValue());
            assertEquals("true", v.getExpectedValue());
        }
    }

    // ------------------------------------------------------------------
    // Appearance 中的 PageBlock 嵌套
    // ------------------------------------------------------------------

    @Test
    @DisplayName("Appearance 中存在 1 层 PageBlock 嵌套时产生一条 WARN 违规项")
    void singleNestedPageBlockProducesWarning() throws IOException {
        Annot annot = compliantAnnot(30);
        Appearance appearance = appearance();
        appearance.addPageBlock(new CT_PageBlock());
        annot.setAppearance(appearance);
        OFDReader reader = readerOf(entity("Page_4", annot));

        List<ArchiveViolation> violations = check(reader);

        assertEquals(1, violations.size(), "嵌套 PageBlock 应产生 1 条违规项，实际: " + descriptions(violations));
        ArchiveViolation v = violations.get(0);
        assertEquals(AnnotationRule.RULE_NAME, v.getRuleName());
        assertEquals(ArchiveViolation.Severity.WARN, v.getSeverity());
        assertTrue(v.getDescription().contains("PageBlock"), "描述应包含 PageBlock，实际: " + v.getDescription());
        assertTrue(v.getDescription().contains("共 1 层"), "描述应包含嵌套层数，实际: " + v.getDescription());
        assertTrue(v.getDescription().contains("ID=30"), "描述应包含注释 ID，实际: " + v.getDescription());
        assertEquals("存在嵌套", v.getActualValue());
        assertEquals("展平", v.getExpectedValue());
        assertEquals("Annots/Annot_Page_4.xml", v.getLocation().getLoc());
    }

    @Test
    @DisplayName("Appearance 中存在 3 层 PageBlock 嵌套时报告层数为 3")
    void threeNestedPageBlocksReportsCount() throws IOException {
        Annot annot = compliantAnnot(31);
        Appearance appearance = appearance();
        appearance.addPageBlock(new CT_PageBlock());
        appearance.addPageBlock(new CT_PageBlock());
        appearance.addPageBlock(new CT_PageBlock());
        annot.setAppearance(appearance);
        OFDReader reader = readerOf(entity("Page_5", annot));

        List<ArchiveViolation> violations = check(reader);

        assertEquals(1, violations.size());
        assertTrue(violations.get(0).getDescription().contains("共 3 层"),
                "描述应报告 3 层嵌套，实际: " + violations.get(0).getDescription());
    }

    @Test
    @DisplayName("深层嵌套只统计 Appearance 的直接 PageBlock 子元素")
    void deepNestedPageBlockCountsOnlyDirectChildren() throws IOException {
        CT_PageBlock inner = new CT_PageBlock();
        inner.addPageBlock(new CT_PageBlock());
        inner.addPageBlock(new CT_PageBlock());

        Annot annot = compliantAnnot(32);
        Appearance appearance = appearance();
