    public void paletteEntryWithoutColorReturnsNull() {
        Palette palette = new Palette();
        palette.addCV(new CV());
        CT_ColorSpace colorSpace = new CT_ColorSpace(OFDColorSpaceType.RGB).setPalette(palette);
        CT_Color color = new CT_Color()
