    public void malformedHexadecimalValueThrowsNumberFormatException() {
        CT_Color color = new CT_Color().setValue(new ST_Array("#GG", "0", "0"));
        assertThrows(NumberFormatException.class, () -> ColorConvert.rgb(null, color));
    }

