package org.ofdrw.converter.font;

import org.junit.jupiter.api.Test;

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Unit tests for {@link NamingTable#read(TTFDataStream)}.
 *
 * <p>The tests build the raw bytes of an OpenType 'name' table in memory and feed them to the
 * production parser through a {@link MemoryTTFDataStream}.  The table is placed at a non zero
 * offset inside the stream so that the parser's seek/offset handling is exercised as well.</p>
 */
class NamingTableReadTests {

    // ------------------------------------------------------------------------------------
    // Helpers
    // ------------------------------------------------------------------------------------

    /** A logical name record: fixed header values plus the raw storage bytes of its string. */
    private static final class Spec {
        final int platform;
        final int encoding;
        final int language;
        final int nameId;
        final byte[] bytes;

        Spec(int platform, int encoding, int language, int nameId, byte[] bytes) {
            this.platform = platform;
            this.encoding = encoding;
            this.language = language;
            this.nameId = nameId;
            this.bytes = bytes;
        }
    }

    private static void writeU16(ByteArrayOutputStream out, int value) {
        out.write((value >>> 8) & 0xFF);
        out.write(value & 0xFF);
    }

    private static byte[] latin1(String s) {
        return s.getBytes(StandardCharsets.ISO_8859_1);
    }

    /** Big-endian UTF-16 bytes (what the production code decodes with {@code UTF_16}). */
    private static byte[] utf16(String s) {
        return s.getBytes(StandardCharsets.UTF_16BE);
    }

    private static byte[] buildTable(int formatSelector, List<Spec> specs) {
        return buildTable(formatSelector, specs, null);
    }

    /**
     * Builds a complete 'name' table.
     *
     * @param explicitOffsets when non null, these values are written as the string offsets instead
     *                        of the automatically computed contiguous offsets (used to craft
     *                        malformed tables).
     */
    private static byte[] buildTable(int formatSelector, List<Spec> specs, int[] explicitOffsets) {
        int n = specs.size();
        int storageStart = 6 + n * 12;

        ByteArrayOutputStream storage = new ByteArrayOutputStream();
        int[] offsets = new int[n];
        for (int i = 0; i < n; i++) {
            offsets[i] = storage.size();
            byte[] b = specs.get(i).bytes;
            storage.write(b, 0, b.length);
        }

        ByteArrayOutputStream out = new ByteArrayOutputStream();
        writeU16(out, formatSelector);
        writeU16(out, n);
        writeU16(out, storageStart);
        for (int i = 0; i < n; i++) {
            Spec s = specs.get(i);
            writeU16(out, s.platform);
            writeU16(out, s.encoding);
            writeU16(out, s.language);
            writeU16(out, s.nameId);
            writeU16(out, s.bytes.length);
            writeU16(out, explicitOffsets == null ? offsets[i] : explicitOffsets[i]);
        }
        byte[] storageBytes = storage.toByteArray();
        out.write(storageBytes, 0, storageBytes.length);
        return out.toByteArray();
    }

    /** Places {@code table} at {@code tableOffset} and runs {@link NamingTable#read}. */
    private static NamingTable readTable(int tableOffset, byte[] table) throws IOException {
        byte[] data = new byte[tableOffset + table.length];
        System.arraycopy(table, 0, data, tableOffset, table.length);
        MemoryTTFDataStream stream = new MemoryTTFDataStream(data);
        NamingTable namingTable = new NamingTable(new long[]{tableOffset, table.length});
        return namingTable.read(stream);
    }

    // ------------------------------------------------------------------------------------
    // Tests
    // ------------------------------------------------------------------------------------

    @Test
    void readParsesWindowsUnicodeFontFamily() throws IOException {
        int tableOffset = 40;
        List<Spec> specs = new ArrayList<>();
        specs.add(new Spec(NameRecord.PLATFORM_WINDOWS,
                NameRecord.ENCODING_WINDOWS_UNICODE_BMP,
                NameRecord.LANGUAGE_WINDOWS_EN_US,
                NameRecord.NAME_FONT_FAMILY_NAME,
                utf16("MyFont")));

        NamingTable table = readTable(tableOffset, buildTable(0, specs));

        assertNotNull(table.getNameRecords());
        assertEquals(1, table.getNameRecords().size());

        NameRecord record = table.getNameRecords().get(0);
        assertEquals(NameRecord.PLATFORM_WINDOWS, record.getPlatformId());
        assertEquals(NameRecord.ENCODING_WINDOWS_UNICODE_BMP, record.getPlatformEncodingId());
        assertEquals(NameRecord.LANGUAGE_WINDOWS_EN_US, record.getLanguageId());
        assertEquals(NameRecord.NAME_FONT_FAMILY_NAME, record.getNameId());
        assertEquals(12, record.getStringLength());
        assertEquals(0, record.getStringOffset());
        assertEquals("MyFont", record.getString());

        assertEquals("MyFont", table.getFontFamily());
        assertEquals("MyFont", table.getName(NameRecord.NAME_FONT_FAMILY_NAME,
                NameRecord.PLATFORM_WINDOWS,
                NameRecord.ENCODING_WINDOWS_UNICODE_BMP,
                NameRecord.LANGUAGE_WINDOWS_EN_US));

        // Absent name / platform / encoding / language combinations resolve to null.
        assertNull(table.getFontSubFamily());
        assertNull(table.getPostScriptName());
        assertNull(table.getName(NameRecord.NAME_FONT_FAMILY_NAME, NameRecord.PLATFORM_UNICODE, 4, 0));
        assertNull(table.getName(NameRecord.NAME_FONT_FAMILY_NAME,
                NameRecord.PLATFORM_WINDOWS,
                NameRecord.ENCODING_WINDOWS_SYMBOL,
                NameRecord.LANGUAGE_WINDOWS_EN_US));
    }

    @Test
    void readParsesMacintoshPostScriptName() throws IOException {
        List<Spec> specs = new ArrayList<>();
        specs.add(new Spec(NameRecord.PLATFORM_MACINTOSH,
                NameRecord.ENCODING_MACINTOSH_ROMAN,
                NameRecord.LANGUAGE_MACINTOSH_ENGLISH,
                NameRecord.NAME_POSTSCRIPT_NAME,
                latin1("HelloPS")));

        NamingTable table = readTable(12, buildTable(1, specs));

        assertEquals(1, table.getNameRecords().size());
        assertEquals("HelloPS", table.getNameRecords().get(0).getString());
        assertEquals("HelloPS", table.getPostScriptName());
    }

    @Test
    void readPrefersMacintoshPostScriptNameOverWindows() throws IOException {
        List<Spec> specs = new ArrayList<>();
        specs.add(new Spec(NameRecord.PLATFORM_MACINTOSH,
                NameRecord.ENCODING_MACINTOSH_ROMAN,
                NameRecord.LANGUAGE_MACINTOSH_ENGLISH,
                NameRecord.NAME_POSTSCRIPT_NAME,
                latin1("MacPS")));
        specs.add(new Spec(NameRecord.PLATFORM_WINDOWS,
                NameRecord.ENCODING_WINDOWS_UNICODE_BMP,
                NameRecord.LANGUAGE_WINDOWS_EN_US,
                NameRecord.NAME_POSTSCRIPT_NAME,
                utf16("WinPS")));

        NamingTable table = readTable(4, buildTable(0, specs));

        assertEquals(2, table.getNameRecords().size());
        assertEquals("MacPS", table.getPostScriptName());
        // The Windows record is still reachable through the lookup table.
        assertEquals("WinPS", table.getName(NameRecord.NAME_POSTSCRIPT_NAME,
                NameRecord.PLATFORM_WINDOWS,
                NameRecord.ENCODING_WINDOWS_UNICODE_BMP,
                NameRecord.LANGUAGE_WINDOWS_EN_US));
    }

    @Test
    void readFallsBackToWindowsPostScriptNameAndTrims() throws IOException {
        List<Spec> specs = new ArrayList<>();
        specs.add(new Spec(NameRecord.PLATFORM_WINDOWS,
                NameRecord.ENCODING_WINDOWS_UNICODE_BMP,
                NameRecord.LANGUAGE_WINDOWS_EN_US,
                NameRecord.NAME_POSTSCRIPT_NAME,
                utf16("  WinPS  ")));

        NamingTable table = readTable(7, buildTable(0, specs));

        // The raw stored value keeps the whitespace, the PostScript name is trimmed.
        assertEquals("  WinPS  ", table.getNameRecords().get(0).getString());
        assertEquals("WinPS", table.getPostScriptName());
    }

    @Test
    void readParsesUnicodePlatformEnglishNamesWithPriority() throws IOException {
        List<Spec> specs = new ArrayList<>();
        // Highest priority: encoding 4 (Unicode 2.0 full repertoire).
        specs.add(new Spec(NameRecord.PLATFORM_UNICODE, NameRecord.ENCODING_UNICODE_2_0_FULL,
                NameRecord.LANGUAGE_UNICODE, NameRecord.NAME_FONT_FAMILY_NAME, utf16("FamFull")));
        // Lower priority for the same name id; must be ignored by getEnglishName.
        specs.add(new Spec(NameRecord.PLATFORM_UNICODE, NameRecord.ENCODING_UNICODE_1_0,
                NameRecord.LANGUAGE_UNICODE, NameRecord.NAME_FONT_FAMILY_NAME, utf16("Fam10")));
        specs.add(new Spec(NameRecord.PLATFORM_UNICODE, NameRecord.ENCODING_UNICODE_2_0_BMP,
                NameRecord.LANGUAGE_UNICODE, NameRecord.NAME_FONT_SUB_FAMILY_NAME, utf16("SubBmp")));

        NamingTable table = readTable(20, buildTable(0, specs));

        assertEquals("FamFull", table.getFontFamily());
        assertEquals("SubBmp", table.getFontSubFamily());
        // Both Unicode family records are present in the lookup table.
        assertEquals("Fam10", table.getName(NameRecord.NAME_FONT_FAMILY_NAME,
                NameRecord.PLATFORM_UNICODE, NameRecord.ENCODING_UNICODE_1_0, NameRecord.LANGUAGE_UNICODE));
    }

    @Test
    void readUsesWindowsAndMacintoshFallbacksForEnglishNames() throws IOException {
        List<Spec> specs = new ArrayList<>();
        specs.add(new Spec(NameRecord.PLATFORM_WINDOWS,
                NameRecord.ENCODING_WINDOWS_UNICODE_BMP,
                NameRecord.LANGUAGE_WINDOWS_EN_US,
                NameRecord.NAME_FONT_FAMILY_NAME,
                utf16("WinFam")));
        specs.add(new Spec(NameRecord.PLATFORM_MACINTOSH,
                NameRecord.ENCODING_MACINTOSH_ROMAN,
                NameRecord.LANGUAGE_MACINTOSH_ENGLISH,
                NameRecord.NAME_FONT_SUB_FAMILY_NAME,
                latin1("MacSub")));

        NamingTable table = readTable(0, buildTable(0, specs));

        assertEquals("WinFam", table.getFontFamily());
        assertEquals("MacSub", table.getFontSubFamily());
    }

    @Test
    void readParsesIsoPlatformEncodings() throws IOException {
        int lang = 7;
        List<Spec> specs = new ArrayList<>();
        // ISO encoding 0 -> US-ASCII
        specs.add(new Spec(NameRecord.PLATFORM_ISO, 0, lang, NameRecord.NAME_COPYRIGHT,
                latin1("Copyright")));
        // ISO encoding 2 -> ISO-8859-1
        specs.add(new Spec(NameRecord.PLATFORM_ISO, 2, lang, NameRecord.NAME_UNIQUE_FONT_ID,
                latin1("caf\u00e9")));
        // ISO encoding 1 -> UTF-16BE
        specs.add(new Spec(NameRecord.PLATFORM_ISO, 1, lang, NameRecord.NAME_FULL_FONT_NAME,
                utf16("BigEndian")));
        // Unknown ISO encoding -> default ISO-8859-1
        specs.add(new Spec(NameRecord.PLATFORM_ISO, 99, lang, NameRecord.NAME_VERSION,
                latin1("Default")));

        NamingTable table = readTable(64, buildTable(0, specs));

        assertEquals("Copyright", table.getName(NameRecord.NAME_COPYRIGHT,
                NameRecord.PLATFORM_ISO, 0, lang));
        assertEquals("caf\u00e9", table.getName(NameRecord.NAME_UNIQUE_FONT_ID,
                NameRecord.PLATFORM_ISO, 2, lang));
        assertEquals("BigEndian", table.getName(NameRecord.NAME_FULL_FONT_NAME,
                NameRecord.PLATFORM_ISO, 1, lang));
        assertEquals("Default", table.getName(NameRecord.NAME_VERSION,
                NameRecord.PLATFORM_ISO, 99, lang));
        // Different language id must not resolve.
        assertNull(table.getName(NameRecord.NAME_COPYRIGHT, NameRecord.PLATFORM_ISO, 0, 8));
    }

    @Test
    void readLeavesStringNullWhenOffsetBeyondTableLength() throws IOException {
        List<Spec> specs = new ArrayList<>();
        specs.add(new Spec(NameRecord.PLATFORM_UNICODE, NameRecord.ENCODING_UNICODE_2_0_FULL,
                NameRecord.LANGUAGE_UNICODE, NameRecord.NAME_FONT_FAMILY_NAME, utf16("Ignored")));

        // A string offset larger than the table length is treated as invalid (PDFBOX-2608).
        byte[] table = buildTable(0, specs, new int[]{60000});

        NamingTable parsed = readTable(8, table);

        assertEquals(1, parsed.getNameRecords().size());
        assertNull(parsed.getNameRecords().get(0).getString());
        assertNull(parsed.getFontFamily());
        assertNull(parsed.getName(NameRecord.NAME_FONT_FAMILY_NAME,
                NameRecord.PLATFORM_UNICODE, NameRecord.ENCODING_UNICODE_2_0_FULL,
                NameRecord.LANGUAGE_UNICODE));
    }

    @Test
    void readWithZeroNameRecordsProducesEmptyTable() throws IOException {
        NamingTable table = readTable(2, buildTable(0, new ArrayList<Spec>()));

        assertNotNull(table.getNameRecords());
        assertTrue(table.getNameRecords().isEmpty());
        assertNull(table.getFontFamily());
        assertNull(table.getFontSubFamily());
        assertNull(table.getPostScriptName());
        assertNull(table.getName(NameRecord.NAME_FONT_FAMILY_NAME,
                NameRecord.PLATFORM_WINDOWS,
                NameRecord.ENCODING_WINDOWS_UNICODE_BMP,
                NameRecord.LANGUAGE_WINDOWS_EN_US));
    }

    @Test
    void readReturnsSameInstanceForChaining() throws IOException {
        List<Spec> specs = new ArrayList<>();
        specs.add(new Spec(NameRecord.PLATFORM_WINDOWS, NameRecord.ENCODING_WINDOWS_SYMBOL,
                NameRecord.LANGUAGE_WINDOWS_EN_US, NameRecord.NAME_FONT_FAMILY_NAME, utf16("SymFam")));

        byte[] table = buildTable(0, specs);
        byte[] data = new byte[table.length];
        System.arraycopy(table, 0, data, 0, table.length);
        MemoryTTFDataStream stream = new MemoryTTFDataStream(data);
        NamingTable namingTable = new NamingTable(new long[]{0, table.length});

        assertSame(namingTable, namingTable.read(stream));
        // Windows symbol encoding is also decoded as UTF-16.
        assertEquals("SymFam", namingTable.getFontFamily());
    }

    @Test
    void readThrowsIOExceptionWhenTableOffsetIsBeyondData() {
        MemoryTTFDataStream stream = new MemoryTTFDataStream(new byte[]{0, 0, 0, 0});
        NamingTable namingTable = new NamingTable(new long[]{1000, 4});

        assertThrows(IOException.class, () -> namingTable.read(stream));
    }

    @Test
    void readThrowsIOExceptionWhenStringStorageIsTruncated() {
        // Header: format=0, numberOfNameRecords=1, storageStart=18.
