    static byte[] buildTtf(Map<String, byte[]> tables) {
        List<String> tags = new ArrayList<>(tables.keySet());
        Collections.sort(tags);
        int n = tags.size();
        int entrySelector = 0;
        while ((1 << (entrySelector + 1)) <= n) entrySelector++;
        int searchRange = (1 << entrySelector) * 16;
        int rangeShift = n * 16 - searchRange;
        ByteArrayOutputStream body = new ByteArrayOutputStream();
        int dirSize = 12 + n * 16;
        int[] offsets = new int[n];
        int cur = dirSize;
        for (int i = 0; i < n; i++) {
            cur = (cur + 3) & ~3;
            offsets[i] = cur;
            cur += tables.get(tags.get(i)).length;
        }
        byte[] out = new byte[cur];
        int p = 0;
        System.arraycopy(u32(0x00010000L), 0, out, 0, 4); p = 4;
        System.arraycopy(u16(n), 0, out, p, 2); p += 2;
        System.arraycopy(u16(searchRange), 0, out, p, 2); p += 2;
        System.arraycopy(u16(entrySelector), 0, out, p, 2); p += 2;
        System.arraycopy(u16(rangeShift), 0, out, p, 2); p += 2;
        for (int i = 0; i < n; i++) {
            byte[] tag = tags.get(i).getBytes(java.nio.charset.StandardCharsets.ISO_8859_1);
            System.arraycopy(tag, 0, out, p, 4); p += 4;
            System.arraycopy(u32(0), 0, out, p, 4); p += 4;
            System.arraycopy(u32(offsets[i]), 0, out, p, 4); p += 4;
            System.arraycopy(u32(tables.get(tags.get(i)).length), 0, out, p, 4); p += 4;
        }
        for (int i = 0; i < n; i++) {
            byte[] d = tables.get(tags.get(i));
            System.arraycopy(d, 0, out, offsets[i], d.length);
        }
        return out;
