    @Test
    @DisplayName("普通 TrueType 字体：解析后返回自身，并从 head 表读取 unitsPerEm")
    void parseTrueTypeFont_readsVersionDirectoryAndHead() throws IOException {
        TrueTypeFont font = new TrueTypeFont();

        TrueTypeFont parsed = font.parse(stream(buildTtf(minimalTableSet(1000, 0))));

        assertSame(font, parsed, "parse(TTFDataStream) 必须返回当前实例");
        // unitsPerEm = 1000 -> 1000.0f / 1000 = 1.0f, 再乘 0.001f
        assertEquals(0.001f, font.getFontMatrix().get(0).floatValue(), 1.0e-9f);
        assertEquals(0.001f, font.getFontMatrix().get(3).floatValue(), 1.0e-9f);
        assertEquals(0, font.getFontMatrix().get(1).floatValue(), 0.0f);
    }

    @Test
    @DisplayName("indexToLocFormat = 0 时按 2 字节读取 loca 表并定位字形数据")
    void parseTrueTypeFont_usesShortLocaOffsets() throws IOException {
        byte[] glyph = oneContourGlyph();
        Map<String, byte[]> tables = minimalTableSet(1000, 0);
        // 3 个偏移量（numGlyphs = 2）：glyph0 为空字形，glyph1 指向真实的 glyf 数据
        tables.put("loca", cat(u16(0), u16(0), u16((glyph.length + 1) / 2)));
        tables.put("glyf", glyph);

        TrueTypeFont font = new TrueTypeFont().parse(stream(buildTtf(tables)));

        GlyphData glyph0 = font.getGlyph(0);
        assertNotNull(glyph0, "gid 0 必须存在");
        assertEquals(0, glyph0.getNumberOfContours(), "长度相同偏移量表示空字形");

        GlyphData glyph1 = font.getGlyph(1);
        assertNotNull(glyph1, "gid 1 必须存在");
        assertEquals(1, glyph1.getNumberOfContours(), "短格式 loca 偏移量应指向真实字形");
        assertEquals(100, glyph1.getXMaximum());
        assertEquals(100, glyph1.getYMaximum());
        // 没有 hmtx 表时 leftSideBearing 取 0，xMin 也是 0，因此首点 x 坐标为 0
        assertEquals(0, glyph1.getDescription().getXCoordinate(0));
    }

    @Test
    @DisplayName("indexToLocFormat = 1 时按 4 字节读取 loca 表并定位字形数据")
    void parseTrueTypeFont_usesLongLocaOffsets() throws IOException {
        byte[] glyph = oneContourGlyph();
        Map<String, byte[]> tables = minimalTableSet(2048, 1);
        tables.put("loca", cat(u32(0L), u32(0L), u32(glyph.length)));
        tables.put("glyf", glyph);

        TrueTypeFont font = new TrueTypeFont().parse(stream(buildTtf(tables)));

        assertEquals(4.8828125e-4f, font.getFontMatrix().get(0).floatValue(), 1.0e-12f);
        GlyphData glyph1 = font.getGlyph(1);
        assertNotNull(glyph1);
        assertEquals(1, glyph1.getNumberOfContours(), "长格式 loca 偏移量应指向真实字形");
        assertEquals(100, glyph1.getXMaximum());
        assertNull(font.getGlyph(2), "gid 超出 numGlyphs 时应返回 null");
        assertNull(font.getGlyph(-1), "非法 gid 应返回 null");
    }

    @Test
    @DisplayName("存在 hhea/hmtx 表时使用其 leftSideBearing 计算字形坐标")
    void parseTrueTypeFont_readsHorizontalMetrics() throws IOException {
        byte[] glyph = oneContourGlyph();
        Map<String, byte[]> tables = minimalTableSet(1000, 0);
        tables.put("loca", cat(u16(0), u16(0), u16(1), u16((glyph.length + 1) / 2)));
        tables.put("maxp", maxp(3));
        tables.put("hhea", hhea(3));
        // 3 个 hMetric：(advanceWidth, leftSideBearing)
        tables.put("hmtx", cat(u16(500), u16(0), u16(500), u16(0), u16(600), u16(-150)));
        tables.put("glyf", glyph);

        TrueTypeFont font = new TrueTypeFont().parse(stream(buildTtf(tables)));

        GlyphData glyph2 = font.getGlyph(2);
