    // ================= 内部工具方法 =================

    private static TrueTypeFont newFont() {
        return new TrueTypeFont();
    }

    private static TTFDataStream stream(byte[] data) {
        return new MemoryTTFDataStream(data);
    }

    private static byte[] resource(String name) throws IOException {
        try (InputStream in = TrueTypeFontParseTests.class.getResourceAsStream(name)) {
            assertNotNull(in, "缺少测试资源：" + name);
            ByteArrayOutputStream out = new ByteArrayOutputStream();
            byte[] buf = new byte[4096];
            int read;
            while ((read = in.read(buf)) != -1) {
                out.write(buf, 0, read);
            }
            return out.toByteArray();
