        assertNotSame(bezier, result.get(0), "B points are rebuilt");
        assertEquals(10f, bezier.x1, "the input B point is not modified");
        assertEquals(60f, bezier.y3, "the input B point is not modified");
        assertMm("the returned point is converted", 10d, result.get(0).x1);
    }

    @Test
    @DisplayName("Legacy 300 DPI absolute paths are detected, rescaled and not passed through the CTM")
    void testLegacyAbsolutePathIsDetected() {
        // raw coordinates of 10 mm / 50 mm expressed in a 300 DPI device space
        double raw10 = 300d * 10d / 25.4d;
        double raw50 = 300d * 50d / 25.4d;
        List<PathPoint> input = listOf(move((float) raw10, (float) raw10),
                new PathPoint("L", (float) raw50, (float) raw50, 0, 0, 0, 0));
        // the declared CTM pushes the path far outside of the page boundary
        ST_Array ctm = new ST_Array(1d, 0d, 0d, 1d, 1000d, 0d);
        ST_Box boundary = new ST_Box(0d, 0d, PAGE_WIDTH, PAGE_HEIGHT);

        List<PathPoint> result = PointUtil.calPdfPathPoint(PAGE_WIDTH, PAGE_HEIGHT, boundary,
                input, true, ctm, null, null, false, 1d);

        assertMm("legacy raw value 300dpi 10mm becomes 10 mm in points", 10d, result.get(0).x1);
        assertMm("legacy raw value 300dpi 10mm becomes 10 mm in points", 10d, result.get(0).y1);
        assertMm("legacy raw value 300dpi 50mm becomes 50 mm in points", 50d, result.get(1).x1);
        assertMm("legacy raw value 300dpi 50mm becomes 50 mm in points", 50d, result.get(1).y1);
        assertNotEquals(raw10 + 1000d, (double) result.get(0).x1, 1d,
                "the CTM must not be applied to legacy absolute coordinates");
    }

    @Test
    @DisplayName("Legacy absolute path detection still applies the origin fix")
    void testLegacyAbsolutePathWithOriginFix() {
        double raw10 = 300d * 10d / 25.4d;
        List<PathPoint> input = listOf(move((float) raw10, (float) raw10),
