        assertMm("CTM scaling is applied", 20d, result.get(0).x1);
        assertMm("CTM scaling is applied", 40d, result.get(0).y1);
    }

    @Test
    @DisplayName("The nine parameter overload behaves like the ten parameter overload with scale 1")
    void testNineParameterOverloadDelegatesWithUnitScale() {
        ST_Box boundary = new ST_Box(3d, 4d, 100d, 100d);
        ST_Array ctm = new ST_Array(1d, 0d, 0d, 1d, 1d, 1d);
        ST_Box compositeBoundary = new ST_Box(2d, 2d, 40d, 40d);

        List<PathPoint> nine = PointUtil.calPdfPathPoint(PAGE_WIDTH, PAGE_HEIGHT, boundary,
                listOf(move(10f, 20f)), true, ctm, compositeBoundary, null, false);
        List<PathPoint> ten = PointUtil.calPdfPathPoint(PAGE_WIDTH, PAGE_HEIGHT, boundary,
                listOf(move(10f, 20f)), true, ctm, compositeBoundary, null, false, 1d);

        assertEquals(ten.size(), nine.size());
        for (int i = 0; i < ten.size(); i++) {
