import org.ofdrw.core.basicType.ST_Box;
import org.ofdrw.core.text.TextCode;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Unit tests for
 * {@link PointUtil#calPdfTextCoordinate(double, double, ST_Box, float, List, boolean, ST_Array, boolean, double)}.
 *
 * <p>The method converts OFD text positioning information into PDF device coordinates.
 * Coordinates are expressed in millimetres and are finally converted to 72 DPI pixels,
 * therefore the expected values below are the millimetre results multiplied by
 * 72/25.4 (2.834645669...).</p>
 */
public class PointUtilCalPdfTextCoordinateTests {

    /**
     * Tolerance used for the millimetre -> 72DPI pixel conversion.
     */
    private static final double EPS = 1e-4;

    /**
     * 72 DPI conversion factor applied by converterDpi.
     */
    private static final double MM_TO_72DPI = 72d / 25.4d;

    private static TextCode code(Double x, Double y, String text) {
        TextCode textCode = new TextCode();
        textCode.setContent(text);
        textCode.setCoordinate(x, y);
        return textCode;
    }

    private static double px(double mm) {
        return mm * MM_TO_72DPI;
    }

    private static void assertPoint(TextCodePoint point, double expectedXmm, double expectedYmm, String expectedText) {
        assertNotNull(point);
        assertEquals(px(expectedXmm), point.getX(), EPS, "unexpected X for glyph '" + expectedText + "'");
        assertEquals(px(expectedYmm), point.getY(), EPS, "unexpected Y for glyph '" + expectedText + "'");
        assertEquals(expectedText, point.getText());
    }

    private static List<String> glyphs(List<TextCodePoint> points) {
        List<String> result = new ArrayList<>(points.size());
        for (TextCodePoint point : points) {
            result.add(point.getText());
        }
        return result;
    }

    private static List<Double> xs(List<TextCodePoint> points) {
        List<Double> result = new ArrayList<>(points.size());
        for (TextCodePoint point : points) {
            result.add(point.getX());
        }
        return result;
    }

    private static List<Double> ys(List<TextCodePoint> points) {
        List<Double> result = new ArrayList<>(points.size());
        for (TextCodePoint point : points) {
            result.add(point.getY());
        }
        return result;
    }

    @Test
    public void onePointPerCharacterAtTheTextCodeOriginWhenNothingElseIsGiven() {
        List<TextCode> textCodes = Collections.singletonList(code(10d, 20d, "ABC"));

        List<TextCodePoint> points = PointUtil.calPdfTextCoordinate(
                210d, 297d, null, 12f, textCodes, false, null, false, 1.0d);

        assertEquals(3, points.size());
        assertEquals(Arrays.asList("A", "B", "C"), glyphs(points));
        // without DeltaX/DeltaY every glyph of a TextCode stays on the TextCode origin
        for (TextCodePoint point : points) {
            assertPoint(point, 10d, 20d, point.getText());
        }
    }

    @Test
    public void htmlEntitiesAreDecodedAndLineBreaksAreRemoved() {
        String raw = "A&lt;B\nC&gt;D&amp;E&nbsp;F&quot;G&apos;H&copy;I";
        List<TextCode> textCodes = Collections.singletonList(code(0d, 0d, raw));

        List<TextCodePoint> points = PointUtil.calPdfTextCoordinate(
                210d, 297d, null, 12f, textCodes, false, null, false, 1.0d);

        // "&copy;" is dropped and "\n" is removed, the remaining entities become single characters
        assertEquals(Arrays.asList("A", "<", "B", "C", ">", "D", "&", "E", " ", "F", "\"", "G", "'", "H", "I"),
                glyphs(points));
        assertEquals(15, points.size());
    }

    @Test
    public void negativeDeltaXOffsetsAreAccumulated() {
        TextCode textCode = code(100d, 50d, "abc");
        textCode.setDeltaX(new ST_Array("-10", "-20"));

        List<TextCodePoint> points = PointUtil.calPdfTextCoordinate(
                210d, 297d, null, 12f, Collections.singletonList(textCode), false, null, false, 1.0d);

        assertEquals(3, points.size());
        // DeltaX holds the distance between two consecutive glyph origins: 100, 90, 70
        assertPoint(points.get(0), 100d, 50d, "a");
        assertPoint(points.get(1), 90d, 50d, "b");
        assertPoint(points.get(2), 70d, 50d, "c");
    }

    @Test
    public void shortDeltaListRepeatsItsLastValueForRemainingGlyphs() {
        TextCode textCode = code(0d, 0d, "abcd");
        textCode.setDeltaX(new ST_Array("10", "20"));

        List<TextCodePoint> points = PointUtil.calPdfTextCoordinate(
                210d, 297d, null, 12f, Collections.singletonList(textCode), false, null, false, 1.0d);

        // 0, +10, +20, +20 (last delta repeated for the trailing glyphs)
        assertEquals(px(0d), points.get(0).getX(), EPS);
        assertEquals(px(10d), points.get(1).getX(), EPS);
        assertEquals(px(30d), points.get(2).getX(), EPS);
        assertEquals(px(50d), points.get(3).getX(), EPS);
    }

    @Test
    public void deltaYIsAppliedIndependentlyFromDeltaX() {
        TextCode textCode = code(0d, 0d, "abc");
        textCode.setDeltaY(new ST_Array("0", "15"));

        List<TextCodePoint> points = PointUtil.calPdfTextCoordinate(
                210d, 297d, null, 12f, Collections.singletonList(textCode), false, null, false, 1.0d);

        assertEquals(3, points.size());
        assertEquals(px(0d), points.get(0).getY(), EPS);
        assertEquals(px(0d), points.get(1).getY(), EPS);
        assertEquals(px(15d), points.get(2).getY(), EPS);
        for (TextCodePoint point : points) {
            assertEquals(0d, point.getX(), EPS);
        }
    }

    @Test
    public void verticalWritingDeltaYAdvancesDownwards() {
        TextCode textCode = code(5d, 5d, "ab");
        textCode.setDeltaY(new ST_Array("12"));

        List<TextCodePoint> points = PointUtil.calPdfTextCoordinate(
                210d, 297d, null, 12f, Collections.singletonList(textCode), false, null, false, 1.0d);

        assertPoint(points.get(0), 5d, 5d, "a");
        assertPoint(points.get(1), 5d, 17d, "b");
    }

    @Test
    public void groupedDeltaNotationIsExpanded() {
        TextCode textCode = code(0d, 0d, "abc");
        // "g 2 5" means: repeat the value 5 twice
        textCode.setDeltaX(new ST_Array("g", "2", "5"));

        List<TextCodePoint> points = PointUtil.calPdfTextCoordinate(
                210d, 297d, null, 12f, Collections.singletonList(textCode), false, null, false, 1.0d);

        assertEquals(3, points.size());
        assertEquals(px(0d), points.get(0).getX(), EPS);
        assertEquals(px(5d), points.get(1).getX(), EPS);
        assertEquals(px(10d), points.get(2).getX(), EPS);
    }

    @Test
    public void deltaLongerThanTheTextIsIgnoredBeyondTheTextLength() {
        TextCode textCode = code(0d, 0d, "ab");
        textCode.setDeltaX(new ST_Array("3", "4", "5", "6"));

        List<TextCodePoint> points = PointUtil.calPdfTextCoordinate(
                210d, 297d, null, 12f, Collections.singletonList(textCode), false, null, false, 1.0d);

        assertEquals(2, points.size());
        assertEquals(px(0d), points.get(0).getX(), EPS);
        assertEquals(px(3d), points.get(1).getX(), EPS);
    }

    @Test
    public void ctmTranslationIsAppliedOnceAndDeltaIsTransformedAsVector() {
        TextCode textCode = code(10d, 20d, "ab");
        textCode.setDeltaX(new ST_Array("5"));
        ST_Array ctm = new ST_Array(1d, 0d, 0d, 1d, 100d, 50d);

        List<TextCodePoint> points = PointUtil.calPdfTextCoordinate(
                210d, 297d, null, 12f, Collections.singletonList(textCode), true, ctm, false, 1.0d);

        assertEquals(2, points.size());
        // origin: (10,20) + translation (100,50) => (110,70)
        assertPoint(points.get(0), 110d, 70d, "a");
        // step: the DeltaX vector (5,0) is transformed without the translation => (110+5, 70)
        assertPoint(points.get(1), 115d, 70d, "b");
    }

    @Test
    public void ctmScaleAndDeltaAreCombinedWithoutTranslationDrift() {
        TextCode textCode = code(1d, 1d, "abc");
        textCode.setDeltaX(new ST_Array("2"));
        // a=2, d=3 scaling, e=10 / f=20 translation
        ST_Array ctm = new ST_Array(2d, 0d, 0d, 3d, 10d, 20d);

        List<TextCodePoint> points = PointUtil.calPdfTextCoordinate(
                210d, 297d, null, 12f, Collections.singletonList(textCode), true, ctm, false, 1.0d);

        assertEquals(3, points.size());
        // origin: (1*2+10, 1*3+20) = (12,23); delta (2,0) scaled by a=2 => +4 in X
        assertPoint(points.get(0), 12d, 23d, "a");
        assertPoint(points.get(1), 16d, 23d, "b");
        assertPoint(points.get(2), 20d, 23d, "c");
    }

    @Test
    public void ctmRotationIsAppliedToBothOriginAndDeltaVector() {
        TextCode textCode = code(0d, 0d, "ab");
        textCode.setDeltaX(new ST_Array("4"));
        // 90 degree rotation: a=0, b=1, c=-1, d=0
        ST_Array ctm = new ST_Array(0d, 1d, -1d, 0d, 0d, 0d);

        List<TextCodePoint> points = PointUtil.calPdfTextCoordinate(
                210d, 297d, null, 12f, Collections.singletonList(textCode), true, ctm, false, 1.0d);

        assertPoint(points.get(0), 0d, 0d, "a");
        // (4,0) rotated by the linear part => (0,4)
        assertPoint(points.get(1), 0d, 4d, "b");
    }

    @Test
    public void boundaryOffsetIsAddedToEveryGlyphOrigin() {
        ST_Box boundary = new ST_Box(1d, 2d, 100d, 200d);
        List<TextCode> textCodes = Collections.singletonList(code(10d, 20d, "ab"));

        List<TextCodePoint> points = PointUtil.calPdfTextCoordinate(
                210d, 297d, boundary, 12f, textCodes, false, null, false, 1.0d);

        assertEquals(2, points.size());
        assertPoint(points.get(0), 11d, 22d, "a");
        assertPoint(points.get(1), 11d, 22d, "b");
    }

    @Test
    public void scaleFactorIsAppliedBeforeTheBoundaryOffset() {
        ST_Box boundary = new ST_Box(1d, 2d, 100d, 200d);
        List<TextCode> textCodes = Collections.singletonList(code(10d, 20d, "a"));

        List<TextCodePoint> points = PointUtil.calPdfTextCoordinate(
                210d, 297d, boundary, 12f, textCodes, false, null, false, 0.5d);

        assertEquals(1, points.size());
        // 10*0.5 + 1 = 6, 20*0.5 + 2 = 12
        assertPoint(points.get(0), 6d, 12d, "a");
    }

    @Test
    public void scaleFactorWithoutBoundaryMultipliesTheCoordinates() {
        List<TextCode> textCodes = Collections.singletonList(code(100d, 200d, "a"));

        List<TextCodePoint> points = PointUtil.calPdfTextCoordinate(
                210d, 297d, null, 12f, textCodes, false, null, false, 0.5d);

        assertPoint(points.get(0), 50d, 100d, "a");
    }

    @Test
    public void fixOriginToPdfFlipsYUsingTheGivenHeight() {
        ST_Box boundary = new ST_Box(1d, 2d, 100d, 200d);
        List<TextCode> textCodes = Collections.singletonList(code(10d, 20d, "a"));

        List<TextCodePoint> flipped = PointUtil.calPdfTextCoordinate(
                210d, 100d, boundary, 12f, textCodes, false, null, true, 1.0d);
        List<TextCodePoint> unflipped = PointUtil.calPdfTextCoordinate(
                210d, 100d, boundary, 12f, textCodes, false, null, false, 1.0d);

        // real Y is 2 + 20 = 22, flipped: 100 - 22 = 78
        assertPoint(unflipped.get(0), 11d, 22d, "a");
        assertPoint(flipped.get(0), 11d, 78d, "a");
    }

    @Test
    public void fixOriginToPdfFlipsYForEachGlyphOfADeltaSequence() {
        TextCode textCode = code(0d, 0d, "abc");
        textCode.setDeltaY(new ST_Array("10"));

        List<TextCodePoint> points = PointUtil.calPdfTextCoordinate(
                210d, 100d, null, 12f, Collections.singletonList(textCode), false, null, true, 1.0d);

        assertEquals(3, points.size());
        assertEquals(px(100d), points.get(0).getY(), EPS);
        assertEquals(px(90d), points.get(1).getY(), EPS);
        assertEquals(px(80d), points.get(2).getY(), EPS);
    }

    @Test
    public void missingCoordinatesAreTreatedAsZero() {
        TextCode textCode = new TextCode();
        textCode.setContent("ab");

        List<TextCodePoint> points = PointUtil.calPdfTextCoordinate(
                210d, 297d, null, 12f, Collections.singletonList(textCode), false, null, false, 1.0d);

        assertEquals(2, points.size());
        assertPoint(points.get(0), 0d, 0d, "a");
        assertPoint(points.get(1), 0d, 0d, "b");
    }

    @Test
    public void missingCoordinateOnlyDefaultsTheMissingAxis() {
        TextCode textCode = code(null, 30d, "a");

        List<TextCodePoint> points = PointUtil.calPdfTextCoordinate(
                210d, 297d, null, 12f, Collections.singletonList(textCode), false, null, false, 1.0d);

        assertPoint(points.get(0), 0d, 30d, "a");
    }

    @Test
    public void hasCtmTrueWithNullCtmBehavesLikeNoTransform() {
        List<TextCode> textCodes = Collections.singletonList(code(10d, 20d, "a"));

        List<TextCodePoint> points = PointUtil.calPdfTextCoordinate(
                210d, 297d, null, 12f, textCodes, true, null, false, 1.0d);

        assertPoint(points.get(0), 10d, 20d, "a");
    }

    @Test
    public void hasCtmFalseIgnoresTheProvidedCtm() {
        List<TextCode> textCodes = Collections.singletonList(code(10d, 20d, "a"));
        ST_Array ctm = new ST_Array(2d, 0d, 0d, 2d, 5d, 5d);

        List<TextCodePoint> points = PointUtil.calPdfTextCoordinate(
                210d, 297d, null, 12f, textCodes, false, ctm, false, 1.0d);

        assertPoint(points.get(0), 10d, 20d, "a");
    }

    @Test
    public void emptyTextProducesNoPoints() {
        List<TextCode> textCodes = Collections.singletonList(code(10d, 20d, ""));

        List<TextCodePoint> points = PointUtil.calPdfTextCoordinate(
                210d, 297d, null, 12f, textCodes, false, null, false, 1.0d);

        assertTrue(points.isEmpty());
    }

    @Test
    public void emptyTextCodeListProducesEmptyResult() {
        List<TextCodePoint> points = PointUtil.calPdfTextCoordinate(
                210d, 297d, null, 12f, new ArrayList<TextCode>(), false, null, false, 1.0d);

        assertNotNull(points);
        assertTrue(points.isEmpty());
    }

    @Test
    public void mixedTextCodesAreReturnedInOrder() {
        List<TextCode> textCodes = new ArrayList<>();
        textCodes.add(code(1d, 2d, "ab"));
        textCodes.add(code(10d, 20d, ""));
        textCodes.add(code(5d, 7d, "cd"));

        List<TextCodePoint> points = PointUtil.calPdfTextCoordinate(
                210d, 297d, null, 12f, textCodes, false, null, false, 1.0d);

        assertEquals(Arrays.asList("a", "b", "c", "d"), glyphs(points));
        assertEquals(px(1d), points.get(0).getX(), EPS);
        assertEquals(px(2d), points.get(0).getY(), EPS);
        assertEquals(px(1d), points.get(1).getX(), EPS);
        assertEquals(px(5d), points.get(2).getX(), EPS);
        assertEquals(px(7d), points.get(2).getY(), EPS);
        assertEquals(px(5d), points.get(3).getX(), EPS);
    }

    @Test
    public void fontSizeDoesNotAffectThisOverloadCoordinates() {
        List<TextCode> small = PointUtil.calPdfTextCoordinate(
                210d, 297d, null, 1f, Collections.singletonList(code(10d, 20d, "ab")), false, null, false, 1.0d);
        List<TextCode> large = PointUtil.calPdfTextCoordinate(
                210d, 297d, null, 96f, Collections.singletonList(code(10d, 20d, "ab")), false, null, false, 1.0d);

        assertEquals(xs(small), xs(large));
        assertEquals(ys(small), ys(large));
    }

    @Test
    public void glyphListKeepsOneEntryPerCharacterForLongText() {
        StringBuilder builder = new StringBuilder();
        for (int i = 0; i < 50; i++) {
            builder.append((char) ('a' + (i % 26)));
        }
        String text = builder.toString();

        List<TextCodePoint> points = PointUtil.calPdfTextCoordinate(
                210d, 297d, null, 12f, Collections.singletonList(code(0d, 0d, text)), false, null, false, 1.0d);

        assertEquals(50, points.size());
        assertEquals(text.substring(0, 1), points.get(0).getText());
        assertEquals(text.substring(49, 50), points.get(49).getText());
    }

    @Test
    public void nullTextFailsFast() {
        TextCode textCode = new TextCode();
        textCode.setCoordinate(1d, 2d);

        assertThrows(NullPointerException.class, () -> PointUtil.calPdfTextCoordinate(
                210d, 297d, null, 12f, Collections.singletonList(textCode), false, null, false, 1.0d));
    }
}
