import java.util.Date;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * {@link GBT35275Validate#validate(String, byte[], byte[])} 的单元测试。
 * <p>
 * 测试中使用的密钥对、证书以及签名值全部在内存中现场生成，不依赖任何外部文件，
 * 保证测试的可重复性与独立性。
 */
@DisplayName("GBT35275 签名验证容器 validate 测试")
public class GBT35275ValidateValidateTests {

    /**
     * BouncyCastle 支持的 SM2 + SM3 签名算法名称
     */
    private static final String SM2_SIGN_ALG = "SM3withSM2";

    private static final Provider BC = new BouncyCastleProvider();

    private static KeyPair keyPair;

    private static X509Certificate certificate;

    private static org.bouncycastle.asn1.x509.Certificate asn1Cert;

    private static byte[] tbsContent;

    private static byte[] tbsDigest;

    @BeforeAll
    static void prepareKeyAndCertificate() throws Exception {
        if (Security.getProvider(BC.getName()) == null) {
            Security.addProvider(BC);
        }
        KeyPairGenerator kpg = KeyPairGenerator.getInstance("EC", BC);
        kpg.initialize(new ECGenParameterSpec("sm2p256v1"), new SecureRandom());
        keyPair = kpg.generateKeyPair();

        X500Name dn = new X500Name("CN=GBT35275 Unit Test, O=OFDRW, C=CN");
        // 使用固定时间构造证书，避免测试结果依赖当前时间

    // 使用固定时间构造证书，避免测试结果依赖当前时间
    Date notBefore = new Date(1600000000000L);
    Date notAfter = new Date(1920000000000L);
    JcaX509v3CertificateBuilder certBuilder = new JcaX509v3CertificateBuilder(
            dn,
            BigInteger.valueOf(20210809L),
            notBefore,
            notAfter,
            dn,
            SubjectPublicKeyInfo.getInstance(keyPair.getPublic().getEncoded()));
    ContentSigner contentSigner = new JcaContentSignerBuilder(SM2_SIGN_ALG)
            .setProvider(BC)
            .build(keyPair.getPrivate());
    certificate = new JcaX509CertificateConverter()
            .setProvider(BC)
            .getCertificate(certBuilder.build(contentSigner));
    asn1Cert = CertTools.asn1(certificate);

    tbsContent = "OFD 电子签名待签名原文 - GBT35275 测试".getBytes(StandardCharsets.UTF_8);
    tbsDigest = new SM3.Digest().digest(tbsContent);
}

// ------------------------------------------------------------------
// 正常场景
// ------------------------------------------------------------------

@Test
@DisplayName("内容为原文摘要且签名正确时验证通过")
void validateReturnsOkWhenDigestContentAndSignatureMatch() throws Exception {
    byte[] signature = sign(tbsDigest);
    byte[] signedValue = toSignedValue(
            buildSignedData(new ContentInfo(OIDs.data, new DEROctetString(tbsDigest)),
                    signerInfoWithoutAttributes(signature),
                    new DERSet(asn1Cert)));

    VerifyInfo info = GBT35275Validate.validate(SM2_SIGN_ALG, tbsContent, signedValue);

    assertNotNull(info);
    assertTrue(info.result, "合法的签名值应当验证通过");
    assertEquals("", info.hit);
}

@Test
@DisplayName("内容为摘要的Base64编码（非规范格式兼容）时验证通过")
void validateReturnsOkWhenContentIsBase64EncodedDigest() throws Exception {
    byte[] plaintext = Base64.encode(tbsDigest);
    byte[] signature = sign(plaintext);
    byte[] signedValue = toSignedValue(
            buildSignedData(new ContentInfo(OIDs.data, new DEROctetString(plaintext)),
                    signerInfoWithoutAttributes(signature),
                    new DERSet(asn1Cert)));

    VerifyInfo info = GBT35275Validate.validate(SM2_SIGN_ALG, tbsContent, signedValue);

    assertTrue(info.result, "兼容 Base64 编码摘要格式，应验证通过");
    assertEquals("", info.hit);
}

@Test
@DisplayName("存在PKCS#9认证属性且摘要、签名均正确时验证通过")
void validateReturnsOkWhenPkcs9AuthenticatedAttributesAreValid() throws Exception {
    ASN1Set authenticatedAttributes = authenticatedAttributes(tbsDigest);
    byte[] signature = sign(authenticatedAttributes.getEncoded("DER"));
    byte[] signedValue = toSignedValue(
            buildSignedData(new ContentInfo(OIDs.data, null),
                    signerInfoWithAttributes(signature, authenticatedAttributes),
                    new DERSet(asn1Cert)));

    VerifyInfo info = GBT35275Validate.validate(SM2_SIGN_ALG, tbsContent, signedValue);

    assertTrue(info.result, "PKCS#9 认证属性合法的签名值应验证通过");
    assertEquals("", info.hit);
}

@Test
@DisplayName("多个签名者签名均合法时验证通过")
void validateReturnsOkWhenAllSignersAreValid() throws Exception {
    ASN1Set signerInfos = new DERSet(new ASN1Encodable[]{
            signerInfoWithoutAttributes(sign(tbsDigest)),
            signerInfoWithoutAttributes(sign(tbsDigest))
    });
    byte[] signedValue = toSignedValue(buildSignedData(
            new ContentInfo(OIDs.data, new DEROctetString(tbsDigest)),
            signerInfos,
            new DERSet(asn1Cert)));

    VerifyInfo info = GBT35275Validate.validate(SM2_SIGN_ALG, tbsContent, signedValue);

    assertTrue(info.result, "全部签名者验签通过时结果应为通过");
    assertEquals("", info.hit);
}


@Test
@DisplayName("内容与认证属性同时存在且均正确时验证通过")
void validateReturnsOkWhenContentAndAuthenticatedAttributesAreBothValid() throws Exception {
    ASN1Set authenticatedAttributes = authenticatedAttributes(tbsDigest);
    byte[] signature = sign(authenticatedAttributes.getEncoded("DER"));
    byte[] signedValue = toSignedValue(
            buildSignedData(new ContentInfo(OIDs.data, new DEROctetString(tbsDigest)),
                    signerInfoWithAttributes(signature, authenticatedAttributes),
                    new DERSet(asn1Cert)));

    VerifyInfo info = GBT35275Validate.validate(SM2_SIGN_ALG, tbsContent, signedValue);

    assertTrue(info.result, "内容与认证属性均合法时应验证通过");
    assertEquals("", info.hit);
}

@Test
@DisplayName("内容为无法Base64解码的杂凑值时返回原文不符")
void validateReturnsErrWhenContentIsNeitherDigestNorBase64() throws Exception {
    // 32 个 0xFF 字节无法被 Base64 解码，进入兼容分支后应直接判定原文不符
    byte[] invalidContent = new byte[32];
    for (int i = 0; i < invalidContent.length; i++) {
        invalidContent[i] = (byte) 0xFF;
    }
    byte[] signature = sign(invalidContent);
    byte[] signedValue = toSignedValue(
            buildSignedData(new ContentInfo(OIDs.data, new DEROctetString(invalidContent)),
                    signerInfoWithoutAttributes(signature),
                    new DERSet(asn1Cert)));

    VerifyInfo info = GBT35275Validate.validate(SM2_SIGN_ALG, tbsContent, signedValue);

    assertFalse(info.result, "内容既非原文摘要也非其Base64编码时不应通过验证");
    assertEquals("待签名原文不符", info.hit);
}

@Test
@DisplayName("内容为其他数据的摘要Base64编码时返回原文不符")
void validateReturnsErrWhenBase64ContentDecodesToAnotherDigest() throws Exception {
    byte[] otherDigest = new SM3.Digest().digest("第三段原文".getBytes(StandardCharsets.UTF_8));
    byte[] base64OfOther = Base64.encode(otherDigest);
    byte[] signature = sign(base64OfOther);
    byte[] signedValue = toSignedValue(
            buildSignedData(new ContentInfo(OIDs.data, new DEROctetString(base64OfOther)),
                    signerInfoWithoutAttributes(signature),
                    new DERSet(asn1Cert)));

    VerifyInfo info = GBT35275Validate.validate(SM2_SIGN_ALG, tbsContent, signedValue);

    assertFalse(info.result, "Base64 解码后的摘要与原文摘要不同，不应通过验证");
    assertEquals("待签名原文不符", info.hit);
}

// ------------------------------------------------------------------
// 待签名原文不符
// ------------------------------------------------------------------

@Test
@DisplayName("签名值中携带的摘要与原文摘要不一致时返回原文不符")
void validateReturnsErrWhenContentDigestDoesNotMatchTbsContent() throws Exception {
    byte[] otherDigest = new SM3.Digest().digest("另一段原文".getBytes(StandardCharsets.UTF_8));
    byte[] signature = sign(otherDigest);
    byte[] signedValue = toSignedValue(
            buildSignedData(new ContentInfo(OIDs.data, new DEROctetString(otherDigest)),
                    signerInfoWithoutAttributes(signature),
                    new DERSet(asn1Cert)));

    VerifyInfo info = GBT35275Validate.validate(SM2_SIGN_ALG, tbsContent, signedValue);

    assertFalse(info.result, "摘要不匹配时不应通过验证");
    assertEquals("待签名原文不符", info.hit);
}

@Test
@DisplayName("PKCS#9 message-digest属性值与原文摘要不一致时返回原文不符")
void validateReturnsErrWhenPkcs9MessageDigestDoesNotMatch() throws Exception {
    byte[] otherDigest = new SM3.Digest().digest("PKCS#9 另一段原文".getBytes(StandardCharsets.UTF_8));
    ASN1Set authenticatedAttributes = authenticatedAttributes(otherDigest);
    byte[] signature = sign(authenticatedAttributes.getEncoded("DER"));
    byte[] signedValue = toSignedValue(
            buildSignedData(new ContentInfo(OIDs.data, null),
