// ------------------------------------------------------------------

@Test
@DisplayName("签名值被篡改时返回签名值不一致")
void validateReturnsErrWhenSignatureIsTampered() throws Exception {
    byte[] signature = sign(tbsDigest);
    // 翻转签名的最后一个字节，破坏签名值
    signature[signature.length - 1] ^= 0x01;
    byte[] signedValue = toSignedValue(
            buildSignedData(new ContentInfo(OIDs.data, new DEROctetString(tbsDigest)),
                    signerInfoWithoutAttributes(signature),
                    new DERSet(asn1Cert)));

    VerifyInfo info = GBT35275Validate.validate(SM2_SIGN_ALG, tbsContent, signedValue);

    assertFalse(info.result, "签名值被篡改时不应通过验证");
    assertEquals("签名值不一致", info.hit);
}

@Test
@DisplayName("签名针对其他数据生成时返回签名值不一致")
void validateReturnsErrWhenSignatureIsOverDifferentData() throws Exception {
