/**
 * Tests for {@link ResManager#addRawWithCache(OFDElement)}.
 */
class ResManagerAddRawWithCacheTests {

    @TempDir
    Path tempDir;

    private DocDir docDir;
    private AtomicInteger maxUnitID;
    private ResManager manager;

    @BeforeEach
    void setUp() {
        docDir = new DocDir(tempDir.resolve("Doc_0"));
        docDir.setDocument(new Document().setCommonData(new CT_CommonData()));
        maxUnitID = new AtomicInteger(100);
        manager = new ResManager(docDir, maxUnitID);
    }

    private Res publicResources() throws Exception {
        return docDir.getPublicRes();
    }

    private Res documentResources() throws Exception {
        return docDir.getDocumentRes();
    }

    @Test
    void returnsNullAndDoesNothingForNullInput() throws Exception {
        assertNull(manager.addRawWithCache(null));

        assertEquals(100, maxUnitID.get());
        assertThrows(FileNotFoundException.class, () -> docDir.getPublicRes());
        assertThrows(FileNotFoundException.class, () -> docDir.getDocumentRes());
        assertTrue(docDir.getDocument().getCommonData().getPublicResList().isEmpty());
        assertTrue(docDir.getDocument().getCommonData().getDocumentResList().isEmpty());
    }

    @Test
    void addsColorSpaceToPublicResourcesAndAssignsNextId() throws Exception {
        CT_ColorSpace colorSpace = new CT_ColorSpace(OFDColorSpaceType.RGB);

        ST_ID id = manager.addRawWithCache(colorSpace);

        assertNotNull(id);
        assertEquals(101L, id.getId().longValue());
        assertEquals(id, colorSpace.getID());
        assertEquals(101, maxUnitID.get());

        List<OFDResource> resources = publicResources().getResources();
        assertEquals(1, resources.size());
        assertTrue(resources.get(0) instanceof ColorSpaces);
        ColorSpaces colorSpaces = (ColorSpaces) resources.get(0);
        assertEquals(1, colorSpaces.getColorSpaces().size());
        assertEquals(id, colorSpaces.getColorSpaces().get(0).getID());
        assertEquals(OFDColorSpaceType.RGB, colorSpaces.getColorSpaces().get(0).getType());

        CT_CommonData commonData = docDir.getDocument().getCommonData();
        assertEquals(1, commonData.getPublicResList().size());
        assertEquals("PublicRes.xml", commonData.getPublicResList().get(0).getLoc());
        assertTrue(commonData.getDocumentResList().isEmpty());
    }

    @Test
    void addsFontToPublicResources() throws Exception {
        CT_Font font = new CT_Font("SimSun");

        ST_ID id = manager.addRawWithCache(font);

        assertEquals(101L, id.getId().longValue());
        assertEquals(id, font.getID());
        assertEquals(101, maxUnitID.get());

        List<Fonts> fontsGroups = publicResources().getFonts();
        assertEquals(1, fontsGroups.size());
        List<CT_Font> fonts = fontsGroups.get(0).getFonts();
        assertEquals(1, fonts.size());
        assertEquals(id, fonts.get(0).getID());
        assertEquals("SimSun", fonts.get(0).getFontName());
    }

    @Test
    void addsDrawParamToDocumentResources() throws Exception {
        CT_DrawParam drawParam = new CT_DrawParam().setLineWidth(2.5);

        ST_ID id = manager.addRawWithCache(drawParam);

        assertEquals(101L, id.getId().longValue());
