        assertThrows(FileNotFoundException.class, () -> docDir.getDocumentRes());
        CT_CommonData commonData = docDir.getDocument().getCommonData();
        assertTrue(commonData.getPublicResList().isEmpty());
        assertTrue(commonData.getDocumentResList().isEmpty());

        OFDElement equivalent = OFDElement.getInstance("CustomResource");
        equivalent.addAttribute("Name", "custom");
        ST_ID secondId = manager.addRawWithCache(equivalent);

        assertEquals(firstId, secondId);
        assertEquals(firstId, equivalent.getObjID());
        assertEquals(101, maxUnitID.get());
