        Double[] arr = null;
        if (dash.length % 2 == 1) {
            // 奇数个参数 第一个参数为 虚线偏移量
            arr = dash;
        } else {
            // 偶数参数 补充一个0作为 虚线偏移量
            arr = new Double[dash.length + 1];
            arr[0] = 0.0;
            System.arraycopy(dash, 0, arr, 1, dash.length);
