        assertSame(div, result[0]);
        assertEquals(20d, boxHeight(div), EPS);
    }

    @Test
    @DisplayName("整体高度仅超出切分高度一点点时被切分")
    void splitWhenBoxJustExceedsSplitHeight() {
        Div div = new Div(100d, 10d);
        div.setMargin(5d, 0d, 5d, 0d);      // 整体高度 20
        Div[] result = div.split(19.999d);
        assertEquals(2, result.length);
    }

    // ---------------------------------------------------------------- Margin 分支

    @Test
    @DisplayName("MarginTop 大于切分高度：第一段仅保留部分 Margin 并成为占位符")
    void splitInMarginBranch() {
        Div div = new Div(100d, 10d);
        div.setMargin(10d, 0d, 0d, 0d);     // heightPlus = 10，整体高度 20

        Div[] result = div.split(5d);
        assertEquals(2, result.length);
        Div first = result[0];
        Div second = result[1];

        assertNotSame(div, first);
        assertNotSame(div, second);
        assertNotSame(first, second);

        assertBox("第一段", first, 5d, 0d, 0d, 0d, 0d, 0d, 0d);
        assertTrue(first.isPlaceholder(), "只有 Margin 的第一段应为占位符");
        assertEquals(5d, boxHeight(first), EPS, "第一段高度应等于切分高度");

        assertBox("第二段", second, 5d, 0d, 0d, 10d, 0d, 0d, 0d);
