        assertEquals(2, result.length);
        assertBox("第一段", result[0], 1d, 1d, 1d, 5d, 0d, 0d, 0d);
        assertFalse(result[0].isPlaceholder());
        assertEquals(8d, boxHeight(result[0]), EPS, "第一段总高度应等于切分高度");

        assertBox("第二段", result[1], 0d, 0d, 0d, 5d, 0d, 0d, 0d);
        assertFalse(result[1].isPlaceholder());
        assertEquals(5d, boxHeight(result[1]), EPS, "第二段应保留被截去的内容高度");
        assertEquals(100d, result[1].getWidth(), EPS);
    }

    @Test
    @DisplayName("内容高度恰好被切分高度容纳：第二段内容高度为 0（边界）")
    void splitInContentBranchBoundary() {
        Div div = new Div(100d, 5d);
        div.setMargin(1d, 0d, 0d, 0d);
        div.setBorder(1d, 0d, 0d, 0d);
        div.setPadding(1d, 0d, 0d, 0d);     // 顶部累计 3，整体高度 8

        Div[] result = div.split(8d - 8d + 8d); // 8d
        result = div.split(8d);
        assertEquals(2, result.length);
        assertBox("第一段", result[0], 1d, 1d, 1d, 5d, 0d, 0d, 0d);
        assertBox("第二段", result[1], 0d, 0d, 0d, 0d, 0d, 0d, 0d);
        assertEquals(0d, boxHeight(result[1]), EPS);
    }

    // ---------------------------------------------------------------- PaddingBottom 分支

    @Test
    @DisplayName("PaddingBottom 被切分：第一段保留部分 Padding，第二段保留残余 Padding")
    void splitInPaddingBottomBranch() {
        Div div = new Div(100d, 4d);
        div.setMargin(1d, 0d, 0d, 0d);
        div.setBorder(1d, 0d, 0d, 0d);
        div.setPadding(1d, 0d, 3d, 0d);     // 整体高度 11

        Div[] result = div.split(8d);
        assertEquals(2, result.length);
        assertBox("第一段", result[0], 1d, 1d, 1d, 4d, 1d, 0d, 0d);
        assertFalse(result[0].isPlaceholder());
        assertEquals(8d, boxHeight(result[0]), EPS);

        assertBox("第二段", result[1], 0d, 0d, 0d, 0d, 2d, 0d, 0d);
        assertFalse(result[1].isPlaceholder());
        assertEquals(2d, boxHeight(result[1]), EPS);
    }

    @Test
    @DisplayName("PaddingBottom 恰好耗尽切分高度：第二段 PaddingBottom 为 0（边界）")
    void splitInPaddingBottomBranchBoundary() {
        Div div = new Div(100d, 4d);
        div.setMargin(1d, 0d, 0d, 0d);
        div.setBorder(1d, 0d, 0d, 0d);
        div.setPadding(1d, 0d, 1d, 0d);     // 整体高度 8

        Div[] result = div.split(8d - 1d);  // 7d，需切开 paddingBottom 之外的空间
        assertEquals(2, result.length);
        assertBox("第一段", result[0], 1d, 1d, 1d, 4d, 0d, 0d, 0d);
        assertBox("第二段", result[1], 0d, 0d, 0d, 0d, 1d, 0d, 0d);
    }

    // ---------------------------------------------------------------- BorderBottom 分支

    @Test
    @DisplayName("BorderBottom 被切分：第一段保留部分 Border，第二段保留残余 Border")
    void splitInBorderBottomBranch() {
        Div div = new Div(100d, 1d);
        div.setMargin(1d, 0d, 0d, 0d);
        div.setBorder(1d, 0d, 4d, 0d);
        div.setPadding(1d, 0d, 1d, 0d);     // 整体高度 9

        Div[] result = div.split(6d);
        assertEquals(2, result.length);
        assertBox("第一段", result[0], 1d, 1d, 1d, 1d, 1d, 1d, 0d);
        assertFalse(result[0].isPlaceholder());
        assertEquals(6d, boxHeight(result[0]), EPS);

        assertBox("第二段", result[1], 0d, 0d, 0d, 0d, 0d, 3d, 0d);
        assertFalse(result[1].isPlaceholder());
        assertEquals(3d, boxHeight(result[1]), EPS);
    }

    @Test
    @DisplayName("BorderBottom 恰好耗尽切分高度：第二段 BorderBottom 为 0（边界）")
    void splitInBorderBottomBranchBoundary() {
        Div div = new Div(100d, 1d);
        div.setMargin(1d, 0d, 0d, 0d);
        div.setBorder(1d, 0d, 1d, 0d);
        div.setPadding(1d, 0d, 1d, 0d);     // 整体高度 6

        Div[] result = div.split(6d - 0d);
        assertEquals(2, result.length);
        assertBox("第一段", result[0], 1d, 1d, 1d, 1d, 1d, 1d, 0d);
        assertBox("第二段", result[1], 0d, 0d, 0d, 0d, 0d, 0d, 0d);
        assertEquals(0d, boxHeight(result[1]), EPS);
    }

    // ---------------------------------------------------------------- MarginBottom 分支

    @Test
    @DisplayName("MarginBottom 被切分：第二段成为仅剩 Margin 的占位符")
    void splitInMarginBottomBranch() {
        Div div = new Div(100d, 1d);
        div.setMargin(1d, 0d, 5d, 0d);
        div.setBorder(1d, 0d, 1d, 0d);
        div.setPadding(1d, 0d, 1d, 0d);     // 整体高度 11

        Div[] result = div.split(8d);
        assertEquals(2, result.length);
        assertBox("第一段", result[0], 1d, 1d, 1d, 1d, 1d, 1d, 2d);
        assertFalse(result[0].isPlaceholder());
        assertEquals(8d, boxHeight(result[0]), EPS);

        assertBox("第二段", result[1], 0d, 0d, 0d, 0d, 0d, 0d, 3d);
        assertTrue(result[1].isPlaceholder(), "仅剩 Margin 的第二段应为占位符");
        assertEquals(3d, boxHeight(result[1]), EPS);
    }

    @Test
    @DisplayName("MarginBottom 恰好耗尽切分高度：第二段 MarginBottom 为 0（边界）")
    void splitInMarginBottomBranchBoundary() {
        Div div = new Div(100d, 1d);
        div.setMargin(1d, 0d, 2d, 0d);
        div.setBorder(1d, 0d, 1d, 0d);
        div.setPadding(1d, 0d, 1d, 0d);     // 整体高度 8

        Div[] result = div.split(8d);
        assertEquals(2, result.length);
        assertBox("第一段", result[0], 1d, 1d, 1d, 1d, 1d, 1d, 2d);
        assertEquals(8d, boxHeight(result[0]), EPS);
        assertBox("第二段", result[1], 0d, 0d, 0d, 0d, 0d, 0d, 0d);
        assertTrue(result[1].isPlaceholder());
        assertEquals(0d, boxHeight(result[1]), EPS);
    }

    // ---------------------------------------------------------------- 克隆与状态隔离

    @Test
    @DisplayName("切分不修改原元素")
    void splitDoesNotMutateSource() {
        Div div = new Div(100d, 10d);
        div.setMargin(2d, 0d, 0d, 0d);
        div.setBorder(5d, 0d, 0d, 0d);
        div.setPadding(1d, 0d, 1d, 0d);

        Div[] result = div.split(4d);
        assertEquals(2, result.length);

        assertBox("原元素", div, 2d, 5d, 1d, 10d, 1d, 0d, 0d);
        assertFalse(div.isPlaceholder());
    }

    @Test
    @DisplayName("切分得到的两段互相独立")
    void splitResultsAreIndependent() {
        Div div = new Div(100d, 10d);
        div.setMargin(1d, 0d, 5d, 0d);
        div.setBorder(1d, 0d, 1d, 0d);
        div.setPadding(1d, 0d, 1d, 0d);

        Div[] result = div.split(8d);
        Div first = result[0];
        Div second = result[1];
        double secondMarginTop = second.getMarginTop();
        double secondBorderBottom = second.getBorderBottom();

        first.setMarginTop(99d).setBorderBottom(77d);

        assertEquals(secondMarginTop, second.getMarginTop(), EPS, "修改第一段不应影响第二段");
        assertEquals(secondBorderBottom, second.getBorderBottom(), EPS, "修改第一段不应影响第二段");
        assertEquals(1d, div.getMarginTop(), EPS, "修改第一段不应影响原元素");
        assertEquals(0d, div.getBorderBottom(), EPS, "修改第一段不应影响原元素");
    }

    @Test
    @DisplayName("水平方向属性在切分后保持不变")
    void splitKeepsHorizontalBoxModel() {
        Div div = new Div(100d, 10d);
        div.setMargin(2d, 3d, 4d, 5d);
        div.setBorder(1d, 2d, 3d, 4d);
        div.setPadding(1d, 2d, 3d, 4d);

        Div[] result = div.split(10d);
        assertEquals(2, result.length);
        for (Div d : result) {
            assertEquals(3d, d.getMarginRight(), EPS);
            assertEquals(5d, d.getMarginLeft(), EPS);
            assertEquals(2d, d.getBorderRight(), EPS);
            assertEquals(4d, d.getBorderLeft(), EPS);
            assertEquals(2d, d.getPaddingRight(), EPS);
            assertEquals(4d, d.getPaddingLeft(), EPS);
            assertEquals(100d, d.getWidth(), EPS);
        }
    }
}
