package org.ofdrw.layout.element;

import org.ofdrw.font.EnvFont;
import org.ofdrw.font.Font;

import java.awt.geom.Rectangle2D;

/**
 * 文字字符块
 *
 * @author 权观宇
 * @since 2020-02-28 05:51:05
 */
public class TxtGlyph {

    /**
     * 文字本身大小
     */
    private Rectangle2D bounds;
    /**
     * 文字
     */
    private final char txt;
    /**
     * 文字字体信息
     */
    private final TextFontInfo textFontInfo;

    public TxtGlyph(char txt, TextFontInfo span) {
        this.txt = txt;
        this.textFontInfo = span;
    }

    /**
     * 返回字体宽度
     *
     * @return 字符宽度(字符宽度 + 字间距)
     */
    public double getW() {
        Font font = textFontInfo.getFont();
        if (font.hasWidthMath()) {
            double w = textFontInfo.getLetterSpacing();
            w += textFontInfo.getFontSize() * font.getCharWidthScale(txt);
            return w;
        }
        if (this.bounds == null) {
            // 分析字体大小
            this.bounds = EnvFont.strBounds(font.getName(),
                    font.getFamilyName(),
                    String.valueOf(txt),
                    textFontInfo.getFontSize());
        }
        return textFontInfo.getLetterSpacing() + bounds.getWidth();
    }

    /**
     * 返回字体高度
     *
     * @return 字符高度
     */
    public double getH() {
        Font font = textFontInfo.getFont();
        if (font.hasWidthMath()) {
            return textFontInfo.getFontSize();
        }
        if (this.bounds == null) {
            // 分析字体大小
            this.bounds = EnvFont.strBounds(font.getName(),
                    font.getFamilyName(),
                    String.valueOf(txt),
                    textFontInfo.getFontSize());
        }
        return bounds.getHeight();
    }
}

    /**
     * 如果元素高度不存在那么设置高度
     * <p>
     * 如果已经设置了高度，该方法不会对该高度造成影响
     *
     * @param height 高度
     */
    private void setHeightIfNotExist(double height) {
        if (getHeight() == null || getHeight() == 0) {
            setHeight(height);
        }
    }

    /**
     * 如果宽度高度不存在那么设置宽度
     * <p>
     * 如果已经设置了宽度，该方法不会对该宽度造成影响
     *
     * @param width 宽度
     */
    private void setWidthIfNotExist(double width) {
        if (getWidth() == null || getWidth() == 0) {
            setWidth(width);
        }
    }


    /**
     * 预布局
     * <p>
     * 该方法主要有渲染器调用，请勿主动调用该方法，除非你知道你在做什么。
     *
     * @param widthLimit 宽度限制
     * @return 元素尺寸
     */
