     */
    private static final double EM = 1.0;
    private static final double FONT_SIZE = 3.0;
    private static final double LINE_SPACE = 2.0;
    private static final double EPS = 1.0e-6;
    /**
     * Height adjustment hard coded in the production code to compensate double precision loss.
     */
    private static final double HEIGHT_FIX = 0.0001;

    private Font font;

    @BeforeEach
    public void setUp() {
