    @Test
    @DisplayName("单行文字在宽度限制内时，段落宽度自适应为行宽")
    public void singleLineUsesAutoWidth() {
        Paragraph p = paragraphWith("abcdef"); // 6 * 3 = 18 宽

        Rectangle rect = p.doPrepare(100.0);

        assertNotNull(rect);
        assertEquals(18.0, rect.getWidth(), EPS, "返回矩形的宽度为最长行宽度");
        assertEquals(lineHeight() + HEIGHT_FIX, rect.getHeight(), EPS, "返回矩形的高度为所有行高度之和加精度补偿");
        assertEquals(18.0, p.getWidth(), EPS, "未设置宽度的段落在完成后宽度为最长行宽度");
        assertEquals(lineHeight() + HEIGHT_FIX, p.getHeight(), EPS);
        assertEquals(1, p.getLines().size(), "文字应全部加入同一行");
        assertEquals(18.0, p.getLines().get(0).getWidth(), EPS);
        assertEquals(100.0, p.getLines().get(0).getLineMaxAvailableWidth(), EPS);
        assertEquals(1, p.getContents().size(), "预布局不改变段落内容");
    }

    @Test
    @DisplayName("宽度自适应时受宽度限制约束，文字被拆分为多行")
    public void autoWidthSplitsLongTextAtLimit() {
        Paragraph p = paragraphWith("abcdef"); // 18 宽，限制为 10

        Rectangle rect = p.doPrepare(10.0);

        assertEquals(2, p.getLines().size(), "18 宽的文字在 10 宽的行内应被拆分为两行");
        assertEquals(9.0, p.getLines().get(0).getWidth(), EPS);
        assertEquals(9.0, p.getLines().get(1).getWidth(), EPS);
        assertEquals(9.0, rect.getWidth(), EPS, "自适应宽度取最长行宽度");
        assertEquals(2 * lineHeight() + HEIGHT_FIX, rect.getHeight(), EPS);
        assertEquals(9.0, p.getWidth(), EPS);
    }

    @Test
    @DisplayName("已设置宽度的段落按该宽度折行，且宽度不会因较大的限制而扩大")
    public void fixedWidthWrapsText() {
        Paragraph p = paragraphWith("abcdef");
        p.setWidth(10.0);

        Rectangle rect = p.doPrepare(100.0);

        assertEquals(2, p.getLines().size());
        assertEquals(9.0, p.getLines().get(0).getWidth(), EPS, "第一行容纳 3 个字符");
        assertEquals(9.0, p.getLines().get(1).getWidth(), EPS, "第二行容纳剩余 3 个字符");
        assertEquals(10.0, p.getWidth(), EPS, "宽度取 min(原宽度, 宽度限制)");
        assertEquals(10.0, rect.getWidth(), EPS);
        assertEquals(2 * lineHeight() + HEIGHT_FIX, rect.getHeight(), EPS);
