        p.setWidth(100.0);

        Rectangle rect = p.doPrepare(20.0);

        assertEquals(1, p.getLines().size(), "18 宽的文字可以放入 20 宽的行中");
        assertEquals(18.0, p.getLines().get(0).getWidth(), EPS);
        assertEquals(20.0, p.getWidth(), EPS);
