        assertEquals(2, p.getLines().size(), "linebreak 元素之后应开始新的一行");
        assertEquals(6.0, p.getLines().get(0).getWidth(), EPS);
        assertEquals(6.0, p.getLines().get(1).getWidth(), EPS);
        assertEquals(2 * lineHeight() + HEIGHT_FIX, rect.getHeight(), EPS);
