        p.setWidth(10.0);

        Rectangle rect = p.doPrepare(100.0);

        assertEquals(2, p.getLines().size());
        assertEquals(9.0, p.getLines().get(0).getWidth(), EPS, "第一行容纳 3 个字符");
        assertEquals(9.0, p.getLines().get(1).getWidth(), EPS, "第二行容纳剩余 3 个字符");
