        p.setWidth(1000.0);
        Span span = new Span(font, 10.0, "abc");
        assertTrue(!span.isIntegrity(), "前置条件：元素可以被分割");
        p.add(span);

        Rectangle rect = p.doPrepare(5.0); // 行宽 5 < 单字符宽 10

        assertTrue(p.getLines().isEmpty(), "首字符都无法放入时应丢弃该系列文字");
        assertEquals(5.0, rect.getWidth(), EPS, "宽度收缩到宽度限制 5");
        assertEquals(HEIGHT_FIX, rect.getHeight(), EPS);
    }

    @Test
    @DisplayName("带有 linebreak 的元素加入后立即换行")
    public void linebreakSpanEndsLine() {
        Paragraph p = new Paragraph();
        p.setDefaultFont(font);
        p.setFontSize(FONT_SIZE);
        p.setWidth(50.0);
        p.add(new Span(font, FONT_SIZE, "ab").setLinebreak(true));
        p.add(new Span(font, FONT_SIZE, "cd"));

        Rectangle rect = p.doPrepare(100.0);

        assertEquals(2, p.getLines().size(), "linebreak 元素之后应开始新的一行");
        assertEquals(6.0, p.getLines().get(0).getWidth(), EPS);
        assertEquals(6.0, p.getLines().get(1).getWidth(), EPS);
        assertEquals(2 * lineHeight() + HEIGHT_FIX, rect.getHeight(), EPS);
        assertEquals(50.0, rect.getWidth(), EPS);
    }

    @Test
    @DisplayName("文字中的换行符被转换为多行")
    public void embeddedNewlineSplitsLines() {
        Paragraph p = paragraphWith("ab\ncd");

        Rectangle rect = p.doPrepare(100.0);

        assertEquals(2, p.getLines().size());
        assertEquals(6.0, p.getLines().get(0).getWidth(), EPS);
        assertEquals(6.0, p.getLines().get(1).getWidth(), EPS);
        assertEquals(6.0, rect.getWidth(), EPS, "自适应宽度为最长行宽度");
        assertEquals(2 * lineHeight() + HEIGHT_FIX, rect.getHeight(), EPS);
    }

    @Test
    @DisplayName("多个换行符产生逐段独立的行")
    public void multipleNewlinesProduceOneLinePerSegment() {
        Paragraph p = paragraphWith("a\nb\nc");

        Rectangle rect = p.doPrepare(100.0);

        assertEquals(3, p.getLines().size());
        for (TxtLineBlock line : p.getLines()) {
            assertEquals(3.0, line.getWidth(), EPS);
        }
        assertEquals(3.0, rect.getWidth(), EPS);
        assertEquals(3 * lineHeight() + HEIGHT_FIX, rect.getHeight(), EPS);
    }

    @Test
    @DisplayName("结尾换行符不会产生额外的空行")
    public void trailingNewlineKeepsSingleLine() {
        Paragraph p = paragraphWith("ab\n");

        Rectangle rect = p.doPrepare(100.0);

        assertEquals(1, p.getLines().size(), "末尾为换行符时最后一行是空行，不会被加入");
        assertEquals(6.0, p.getLines().get(0).getWidth(), EPS);
        assertEquals(lineHeight() + HEIGHT_FIX, rect.getHeight(), EPS);
        assertEquals(6.0, rect.getWidth(), EPS);
