        p.setHeight(0d);

        Rectangle rect = p.doPrepare(100.0);

        assertEquals(2 * lineHeight() + HEIGHT_FIX, p.getHeight(), EPS);
        assertEquals(2 * lineHeight() + HEIGHT_FIX, rect.getHeight(), EPS);
