        p.setWidth(10.0);

        Rectangle rect = p.doPrepare(100.0);

        assertTrue(p.getLines().isEmpty());
        assertEquals(HEIGHT_FIX, rect.getHeight(), EPS);
        assertEquals(HEIGHT_FIX, p.getHeight(), EPS);
