        assertNull(p.getWidth(), "异常发生时宽度仍未被设置");
    }

    @Test
    @DisplayName("padding、border、margin 参与宽度限制计算并体现在返回矩形中")
    public void boxModelIsIncludedInRectangle() {
        Paragraph p = paragraphWith("abcdef");
        p.setPadding(1d, 2d, 3d, 4d);      // 上右下左
        p.setBorder(0.5d, 1d, 0.5d, 1d);
        p.setMargin(0d, 0.5d, 0d, 0.5d);
        // widthPlus  = margin(0.5+0.5) + padding(2+4) + border(1+1) = 9
        // heightPlus = padding(1+3) + border(0.5+0.5) = 5

        Rectangle rect = p.doPrepare(100.0);

        assertEquals(1, p.getLines().size());
        assertEquals(91.0, p.getLines().get(0).getLineMaxAvailableWidth(), EPS,
