        assertEquals(18.0, p.getWidth(), EPS);
        assertEquals(18.0 + 9.0, rect.getWidth(), EPS);
        assertEquals(lineHeight() + HEIGHT_FIX + 5.0, rect.getHeight(), EPS);
    }

