    @DisplayName("首行缩进在行首插入占位符并计入行宽")
    public void firstLineIndentAddsPlaceholder() {
        Paragraph p = paragraphWith("abcdef");
        p.setFirstLineIndent(1);

        Rectangle rect = p.doPrepare(100.0);

        assertEquals(1, p.getLines().size());
        LinkedList<Span> inlineSpans = (LinkedList<Span>) p.getLines().get(0).getInlineSpans();
        assertEquals(2, inlineSpans.size());
        Span first = inlineSpans.get(0);
        assertTrue(first instanceof PlaceholderSpan, "行首应为缩进占位符");
        assertEquals(3.0, ((PlaceholderSpan) first).getHoldWidth(), EPS, "缩进 1 个字符 = 字号 3");
