        p.setWidth(10.0);

        Rectangle rect = p.doPrepare(100.0);

        assertEquals(1, p.getLines().size(), "宽度恰好等于行宽不算溢出");
        assertEquals(10.0, p.getLines().get(0).getWidth(), EPS);
        assertEquals(1.0 + LINE_SPACE + HEIGHT_FIX, rect.getHeight(), EPS);
        assertEquals(10.0, rect.getWidth(), EPS);
    }

    @Test
    @DisplayName("超出 1 个字符宽度时被拆分为两行")
    public void oneGlyphOverflowIsSplit() {
        Paragraph p = new Paragraph("abcdefghijk", 1.0, font); // 11 字符 * 1 = 11 宽
        p.setWidth(10.0);

        Rectangle rect = p.doPrepare(100.0);

        assertEquals(2, p.getLines().size());
        assertEquals(10.0, p.getLines().get(0).getWidth(), EPS);
        assertEquals(1.0, p.getLines().get(1).getWidth(), EPS);
        assertEquals(2 * (1.0 + LINE_SPACE) + HEIGHT_FIX, rect.getHeight(), EPS);
        assertEquals(10.0, rect.getWidth(), EPS);
    }

    @Test
    @DisplayName("多次预布局结果一致且不会累积行缓存")
    public void prepareIsRepeatable() {
        Paragraph p = paragraphWith("abcdef");
        p.setWidth(10.0);

        Rectangle first = p.doPrepare(100.0);
        int linesAfterFirst = p.getLines().size();
        Rectangle second = p.doPrepare(100.0);

        assertEquals(2, linesAfterFirst);
        assertEquals(linesAfterFirst, p.getLines().size(), "行缓存在每次预布局前被清空");
        assertEquals(first.getWidth(), second.getWidth(), EPS);
        assertEquals(first.getHeight(), second.getHeight(), EPS);
        assertEquals(1, p.getContents().size(), "预布局不消耗段落内容");
    }

    @Test
    @DisplayName("多个文字单元依次填充行，溢出部分拆分到下一行")
    public void splitAcrossMultipleSpans() {
        Paragraph p = new Paragraph();
        p.setWidth(10.0);
        p.add(new Span(font, FONT_SIZE, "abcd")); // 12 宽
        p.add(new Span(font, FONT_SIZE, "efg"));  // 9 宽

        Rectangle rect = p.doPrepare(100.0);

        assertEquals(3, p.getLines().size());
        assertEquals(9.0, p.getLines().get(0).getWidth(), EPS, "第一行放下 abcd 的前 3 个字符");
        assertEquals(9.0, p.getLines().get(1).getWidth(), EPS, "第二行容纳 d 与 ef");
        assertEquals(3.0, p.getLines().get(2).getWidth(), EPS, "第三行仅剩 g");
        assertEquals(3 * lineHeight() + HEIGHT_FIX, rect.getHeight(), EPS);
        assertEquals(10.0, rect.getWidth(), EPS);
    }

    @Test
    @DisplayName("行高取行内最高文字的高度")
    public void lineHeightFollowsTallestSpan() {
        Paragraph p = new Paragraph();
        p.setDefaultFont(font);
        p.add(new Span(font, 4.0, "abcd")); // 16 宽, 高 4
        p.add(new Span(font, 2.0, "ab"));   // 4 宽, 高 2

        Rectangle rect = p.doPrepare(100.0);

        assertEquals(1, p.getLines().size());
        assertEquals(20.0, p.getLines().get(0).getWidth(), EPS);
        assertEquals(4.0, p.getLines().get(0).getMaxSpanHeight(), EPS);
        assertEquals(4.0 + LINE_SPACE + HEIGHT_FIX, rect.getHeight(), EPS);
        assertEquals(20.0, p.getWidth(), EPS);
    }
