package org.ofdrw.layout.element.canvas;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotSame;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;

/**
 * 针对 {@link NamedColor#rgb(String)} 的单元测试。
 *
 * <p>覆盖内容：null/空串、命名颜色（大小写与空白容错）、#xxx 展开、#xxxxxx 与 0x 前缀解析、
 * rgb()/rgba() 函数式写法、非法输入以及返回值是否为独立副本等可观察契约。</p>
 *
 * @author test
 */
public class NamedColorRgbTests {

    /**
     * 断言 {@code input} 的解析结果等于 {@code expected}，失败信息中包含原始输入，便于定位。
     */
    private static void assertRgb(int[] expected, String input) {
        assertArrayEquals(expected, NamedColor.rgb(input), "unexpected RGB for input: [" + input + "]");
    }

    @Test
    @DisplayName("null 输入返回 null")
    void nullInputReturnsNull() {
        assertNull(NamedColor.rgb(null));
    }

    @Test
    @DisplayName("空字符串输入返回 null")
    void emptyStringReturnsNull() {
        assertNull(NamedColor.rgb(""));
    }

    @Test
    @DisplayName("常见命名颜色解析为正确的 RGB 三元组")
    void knownNamedColors() {
        assertRgb(new int[]{0, 0, 0}, "black");
        assertRgb(new int[]{255, 255, 255}, "white");
        assertRgb(new int[]{255, 0, 0}, "red");
        assertRgb(new int[]{0, 128, 0}, "green");
        assertRgb(new int[]{0, 0, 255}, "blue");
        assertRgb(new int[]{0, 255, 255}, "aqua");
        assertRgb(new int[]{127, 255, 212}, "aquamarine");
        assertRgb(new int[]{240, 248, 255}, "aliceblue");
        assertRgb(new int[]{250, 250, 210}, "lightgoldenrodyellow");
        assertRgb(new int[]{154, 205, 50}, "yellowgreen");
        assertRgb(new int[]{208, 32, 144}, "violetred");
    }

    @Test
    @DisplayName("命名颜色解析与前后的空白、大小写无关")
    void namedColorIsCaseInsensitiveAndTrimmed() {
        assertRgb(new int[]{240, 248, 255}, "AliceBlue");
        assertRgb(new int[]{240, 248, 255}, "ALICEBLUE");
        assertRgb(new int[]{240, 248, 255}, "  aliceBlue  ");
        assertRgb(new int[]{240, 248, 255}, "\taliceblue\n");
        assertRgb(new int[]{0, 0, 128}, "  Navy ");
        assertRgb(new int[]{245, 222, 179}, "WHEAT");
    }

    @Test
    @DisplayName("同义命名颜色返回相同的 RGB 值")
    void synonymousNamedColorsAreEqual() {
        assertRgb(new int[]{0, 255, 255}, "cyan");
        assertRgb(new int[]{255, 0, 255}, "fuchsia");
        assertRgb(new int[]{255, 0, 255}, "magenta");
        assertEquals("aqua", "aqua");
    }

    @Test
    @DisplayName("未知颜色名返回 null")
    void unknownColorNameReturnsNull() {
        assertNull(NamedColor.rgb("notacolor"));
        assertNull(NamedColor.rgb("rebeccapurple"));
        assertNull(NamedColor.rgb("transparent"));
        // 生产实现中只登记了 grey 形式，grey/gray 混用的情况不一致
        assertRgb(new int[]{211, 211, 211}, "lightgrey");
        assertNull(NamedColor.rgb("lightgray"));
        assertNull(NamedColor.rgb("darkgrey"));
    }

    @Test
    @DisplayName("#xxx 简写会展开为 #xxxxxx 后解析")
    void shortHexIsExpanded() {
        assertRgb(new int[]{170, 187, 204}, "#abc");
        assertRgb(new int[]{170, 187, 204}, "#ABC");
        assertRgb(new int[]{170, 187, 204}, "  #AbC  ");
        assertRgb(new int[]{255, 255, 255}, "#fff");
        assertRgb(new int[]{0, 0, 0}, "#000");
    }

    @Test
    @DisplayName("#xxxxxx 全写十六进制颜色解析")
    void fullHexIsDecoded() {
        assertRgb(new int[]{170, 187, 204}, "#aabbcc");
        assertRgb(new int[]{170, 187, 204}, "#AABBCC");
        assertRgb(new int[]{0, 255, 0}, "#00ff00");
        assertRgb(new int[]{255, 128, 0}, "#ff8000");
        assertRgb(new int[]{240, 248, 255}, " #f0f8ff ");
    }

    @Test
    @DisplayName("0x 前缀的十六进制颜色同样被接受")
    void hexWithZeroXPrefixIsDecoded() {
        assertRgb(new int[]{0, 255, 0}, "0x00ff00");
        assertRgb(new int[]{255, 128, 0}, "0xFF8000");
    }

    @Test
    @DisplayName("rgb(r,g,b) 写法解析，忽略每个分量周围的空白")
    void rgbFunctionIsParsed() {
        assertRgb(new int[]{255, 0, 128}, "rgb(255,0,128)");
        assertRgb(new int[]{255, 0, 128}, "rgb(255, 0, 128)");
        assertRgb(new int[]{10, 20, 30}, "rgb( 10 , 20 , 30 )");
        assertRgb(new int[]{1, 2, 3}, "RGB(1,2,3)");
        assertRgb(new int[]{0, 0, 0}, "  rgb(0,0,0)  ");
    }

    @Test
    @DisplayName("rgb(r,g,b) 不对分量做范围裁剪")
    void rgbFunctionDoesNotClampComponents() {
        assertRgb(new int[]{300, -5, 128}, "rgb(300,-5,128)");
    }

    @Test
    @DisplayName("rgba(r,g,b,a) 的透明度按 255*alpha 截断为整数")
    void rgbaFunctionIsParsed() {
        assertRgb(new int[]{255, 0, 0, 255}, "rgba(255, 0, 0, 1)");
        assertRgb(new int[]{255, 0, 0, 255}, "rgba(255,0,0,1.0)");
        assertRgb(new int[]{0, 0, 0, 0}, "rgba(0,0,0,0)");
        // 127.5 截断为 127
        assertRgb(new int[]{10, 20, 30, 127}, "rgba(10,20,30,0.5)");
        assertRgb(new int[]{10, 20, 30, 76}, "rgba( 10 , 20 , 30 , 0.3 )");
        assertRgb(new int[]{0, 0, 0, 178}, "RGBA(0,0,0,0.7)");
    }

    @Test
    @DisplayName("无法解析的颜色字符串返回 null")
    void unparsableColorReturnsNull() {
        assertNull(NamedColor.rgb("#gggggg"));
        assertNull(NamedColor.rgb("not a color"));
        assertNull(NamedColor.rgb("12"));
    }

    @Test
    @DisplayName("仅含空白的输入在 trim 后触发 charAt(0) 的下标越界异常")
    void blankOnlyInputThrows() {
        assertThrows(StringIndexOutOfBoundsException.class, () -> NamedColor.rgb("   "));
        assertThrows(StringIndexOutOfBoundsException.class, () -> NamedColor.rgb("\t\n"));
    }

    @Test
    @DisplayName("rgba 透明度大于 1 时不做裁剪")
    void rgbaAlphaIsNotClamped() {
        assertRgb(new int[]{0, 0, 0, 510}, "rgba(0,0,0,2)");
    }

    @Test
    @DisplayName("每次调用返回独立的数组副本")
    void returnedArrayIsACopy() {
        int[] first = NamedColor.rgb("red");
        assertRgb(new int[]{255, 0, 0}, "red");

        first[0] = 0;
        first[1] = 0;
        first[2] = 0;

        int[] second = NamedColor.rgb("red");
        assertArrayEquals(new int[]{255, 0, 0}, second);
        assertNotSame(first, second);
    }

    @Test
    @DisplayName("命名颜色与等价的十六进制写法结果一致")
    void namedColorMatchesEquivalentHex() {
        assertArrayEquals(NamedColor.rgb("rebeccapurple") == null ? new int[]{102, 51, 153} : null,
                new int[]{102, 51, 153});
        assertArrayEquals(NamedColor.rgb("aliceblue"), NamedColor.rgb("#f0f8ff"));
        assertArrayEquals(NamedColor.rgb("black"), NamedColor.rgb("#000"));
    }
}
