/**
 * 针对 {@link ResManager#addRawWithCache(OFDElement)} 的单元测试。
 *
 * <p>覆盖：空值处理、ID 分配、基于序列化 Hash 的缓存去重、已有 ID 的忽略、
 * 以及不同类型的资源被归类到公共资源或文档资源清单中的可观测副作用。</p>
 */
public class ResManagerAddRawWithCacheTests {

    /**
     * 每个测试独立的临时工作目录（模拟 OFD 包根目录）
     */
    @TempDir
    Path tempDir;

    private OFDDir ofdDir;

    private DocDir docDir;

    private AtomicInteger maxUnitID;

    @BeforeEach
    void setUp() {
        ofdDir = new OFDDir(tempDir);
        docDir = new DocDir(tempDir.resolve("Doc_0"));
        docDir.setDocument(new Document().setCommonData(new CT_CommonData().setMaxUnitID(0)));
        maxUnitID = new AtomicInteger(100);
    }

    /**
     * 使用当前测试的文档容器构建资源管理器
     */
    private ResManager newManager() {
        return new ResManager(ofdDir, docDir, maxUnitID);
    }

    /**
     * 取出指定类型的资源集合（不存在时返回 null）
     */
    private static <T extends OFDResource> T findResource(Res res, Class<T> type) {
        assertNotNull(res, "资源清单不应为空");
        for (OFDResource item : res.getResources()) {
            if (type.isInstance(item)) {
                return type.cast(item);
            }
        }
        return null;
    }

    /**
     * 统计指定类型的资源集合的数量
     */
    private static <T extends OFDResource> int countResource(Res res, Class<T> type) {
        int count = 0;
        for (OFDResource item : res.getResources()) {
            if (type.isInstance(item)) {
                count++;
            }
        }
        return count;
    }

    @Test
    @DisplayName("传入 null 时返回 null 且不产生任何副作用")
    void addRawWithCacheNullArgument() {
        ResManager manager = newManager();

        ST_ID id = manager.addRawWithCache(null);

        assertNull(id, "null 资源对象应返回 null");
        assertTrue(manager.getNewResIds().isEmpty(), "不应记录任何新资源ID");
        assertFalse(docDir.exist(DocDir.PublicResFileName), "不应创建公共资源文件");
        assertFalse(docDir.exist(DocDir.DocumentResFileName), "不应创建文档资源文件");
        assertEquals(100, maxUnitID.get(), "ID 自增器不应被消耗");
    }

    @Test
    @DisplayName("首次加入绘制参数：分配自增ID、设置对象ID、记录新资源、写入文档资源")
    void firstDrawParamIsAssignedNewIdAndStoredInDocumentRes() throws Exception {
        ResManager manager = newManager();
        CT_DrawParam param = new CT_DrawParam().setLineWidth(2.5);

        ST_ID id = manager.addRawWithCache(param);

        assertNotNull(id, "应返回新分配的资源ID");
        assertEquals(101L, id.getId().longValue(), "资源ID应取自增器的下一个值");
        assertEquals(101, maxUnitID.get(), "自增器应被推进一次");
        assertEquals(id, param.getObjID(), "资源对象上应设置该ID");

        assertEquals(1, manager.getNewResIds().size(), "应仅记录一个新增资源ID");
        assertEquals(id, manager.getNewResIds().get(0));

        // 绘制参数属于文档资源
        assertTrue(docDir.exist(DocDir.DocumentResFileName), "应创建文档资源文件");
        assertFalse(docDir.exist(DocDir.PublicResFileName), "不应创建公共资源文件");
        Res docRes = docDir.getDocumentRes();
        assertEquals(1, countResource(docRes, DrawParams.class), "应存在一个绘制参数集合");
        DrawParams drawParams = findResource(docRes, DrawParams.class);
        List<CT_DrawParam> stored = drawParams.getDrawParams();
        assertEquals(1, stored.size());
        assertEquals(id, stored.get(0).getObjID());
        assertEquals(2.5, stored.get(0).getLineWidth().doubleValue(), 1e-9);

        // 文档 CommonData 中登记了文档资源清单
        List<ST_Loc> docResList = docDir.getDocument().getCommonData().getDocumentResList();
        assertEquals(1, docResList.size());
        assertEquals("DocumentRes.xml", docResList.get(0).toString());
    }

    @Test
    @DisplayName("相同内容的两个不同绘制参数对象复用同一个资源ID，且不会重复入库")
    void duplicateDrawParamReusesCachedId() {
        ResManager manager = newManager();
        CT_DrawParam first = new CT_DrawParam().setLineWidth(1.0).setCap(LineCapType.Round);
        ST_ID firstId = manager.addRawWithCache(first);

        CT_DrawParam second = new CT_DrawParam().setLineWidth(1.0).setCap(LineCapType.Round);
        ST_ID secondId = manager.addRawWithCache(second);

        assertEquals(firstId, secondId, "内容一致应复用已有资源ID");
        assertEquals(firstId, second.getObjID(), "复用时应把已有ID设置到新对象上");
        assertEquals(1, manager.getNewResIds().size(), "复用不应记录新的资源ID");
        assertEquals(101, maxUnitID.get(), "复用不应消耗ID自增器");

        DrawParams drawParams = findResource(docDir.getDocumentRes(), DrawParams.class);
        assertEquals(1, drawParams.getDrawParams().size(), "资源集合中不应出现重复对象");
        assertEquals(firstId, drawParams.getDrawParams().get(0).getObjID());
    }

    @Test
    @DisplayName("内容不同则分配不同ID并分别入库")
    void differentContentGetsDistinctIds() {
        ResManager manager = newManager();

        ST_ID idA = manager.addRawWithCache(new CT_DrawParam().setLineWidth(1.0));
        ST_ID idB = manager.addRawWithCache(new CT_DrawParam().setLineWidth(2.0));

        assertNotNull(idA);
        assertNotNull(idB);
        assertEquals(101L, idA.getId().longValue());
        assertEquals(102L, idB.getId().longValue());
        assertEquals(2, manager.getNewResIds().size());
        assertEquals(idA, manager.getNewResIds().get(0));
        assertEquals(idB, manager.getNewResIds().get(1));

        DrawParams drawParams = findResource(docDir.getDocumentRes(), DrawParams.class);
        assertEquals(2, drawParams.getDrawParams().size());
    }

    @Test
    @DisplayName("对象上已有的ID会被忽略（不参与缓存比较），并替换为新分配的ID")
    void existingIdIsIgnoredAndReplaced() {
        ResManager manager = newManager();
        CT_DrawParam withOldId = new CT_DrawParam().setLineWidth(4.0);
        withOldId.setObjID(new ST_ID(777L));

        ST_ID id = manager.addRawWithCache(withOldId);

        assertEquals(101L, id.getId().longValue(), "应使用自增器分配的ID而不是对象原有ID");
        assertEquals(id, withOldId.getObjID(), "对象ID应被替换");

        // 另一个对象内容相同但带有不同的旧ID，也应命中缓存
        CT_DrawParam otherWithOldId = new CT_DrawParam().setLineWidth(4.0);
        otherWithOldId.setObjID(new ST_ID(888L));
        ST_ID reusedId = manager.addRawWithCache(otherWithOldId);

        assertEquals(id, reusedId, "旧ID不参与缓存比较，内容一致应复用");
        assertEquals(id, otherWithOldId.getObjID());
        assertEquals(1, manager.getNewResIds().size());
    }

    @Test
    @DisplayName("同一个对象重复加入只登记一次，返回相同ID")
    void sameInstanceAddedTwiceIsCached() {
        ResManager manager = newManager();
