        ST_ID fontId = manager.addRawWithCache(new CT_Font().setFontName("FontC"));
        ST_ID colorId = manager.addRawWithCache(new CT_ColorSpace(OFDColorSpaceType.GRAY));
        ST_ID paramId = manager.addRawWithCache(new CT_DrawParam().setLineWidth(7.0));
        ST_ID mediaId = manager.addRawWithCache(new CT_MultiMedia()
                .setType(MediaType.Video)
                .setFormat("MP4")
                .setMediaFile(ST_Loc.getInstance("Res/video_0.mp4")));
        ST_ID vectorId = manager.addRawWithCache(new CT_VectorG().setWidth(3D).setHeight(4D));

        assertEquals(101L, fontId.getId().longValue());
        assertEquals(102L, colorId.getId().longValue());
