        List<ST_ID> newIds = manager.getNewResIds();
        assertEquals(5, newIds.size());
        assertEquals(fontId, newIds.get(0));
        assertEquals(colorId, newIds.get(1));
        assertEquals(paramId, newIds.get(2));
        assertEquals(mediaId, newIds.get(3));
        assertEquals(vectorId, newIds.get(4));

        Res pubRes = docDir.getPublicRes();
        assertEquals(1, countResource(pubRes, Fonts.class));
        assertEquals(1, countResource(pubRes, ColorSpaces.class));

        Res docRes = docDir.getDocumentRes();
        assertEquals(1, countResource(docRes, DrawParams.class));
        assertEquals(1, countResource(docRes, MultiMedias.class));
        assertEquals(1, countResource(docRes, CompositeGraphicUnits.class));
    }

