    @DisplayName("tryAdd(null) 返回 true 且不改变空段状态")
    public void testNullIntoEmptySegment() {
        Segment segment = new Segment(100);

        assertTrue(segment.tryAdd(null), "null 元素被视为加入成功");

        assertTrue(segment.isEmpty(), "段应仍为空");
        assertEquals(0, segment.getContent().size(), "内容列表不应有元素");
        assertEquals(0, segment.getSizeList().size(), "尺寸列表不应有元素");
        assertEquals(0d, segment.getHeight(), DELTA, "空段高度为 0");
        assertEquals(100d, segment.getWidth(), DELTA, "段宽度不应变化");
        assertFalse(segment.isBlockable(), "空段默认不可拆分");
        assertFalse(segment.isRemainAreaFiller(), "空段不是剩余空间填充段");
    }

    @Test
    @DisplayName("空间耗尽后 tryAdd(null) 依然返回 true（null 检查最先执行）")
    public void testNullAfterSpaceExhausted() {
        Segment segment = new Segment(100);
        Div<Div> block = div(40, 20);

        assertTrue(segment.tryAdd(block), "独占元素应可加入空段");
        assertTrue(segment.tryAdd(null), "null 元素应直接返回 true");
        assertEquals(1, segment.getContent().size(), "内容列表仍只有 1 个元素");
        assertFalse(segment.tryAdd(div(10, 10)), "空间已耗尽，普通元素不可加入");
    }

    // ---------------------------------------------------------------
    // 独占（块级）元素
    // ---------------------------------------------------------------

    @Test
    @DisplayName("独占元素加入空段：占用整段宽度，反复加入被拒绝")
    public void testBlockElementOccupiesWholeSegment() {
        Segment segment = new Segment(100);
        Div<Div> block = div(40, 20);
        assertTrue(block.isBlockElement(), "默认 Div 为独占元素");

        assertTrue(segment.tryAdd(block), "独占元素可加入空段");

        assertEquals(1, segment.getContent().size(), "段内应含有 1 个元素");
        assertSame(block, segment.getContent().get(0), "段内元素应为加入的元素");
        assertEquals(1, segment.getSizeList().size(), "尺寸序列应含有 1 个矩形");
        assertEquals(40d, segment.getSizeList().get(0).getWidth(), DELTA, "元素宽度为 40");
        assertEquals(20d, segment.getSizeList().get(0).getHeight(), DELTA, "元素高度为 20");
        assertEquals(20d, segment.getHeight(), DELTA, "段高度取元素高度");

        assertFalse(segment.isEmpty(), "段不再为空");
        assertFalse(segment.tryAdd(leftFlow(10, 10)), "独占元素耗尽剩余宽度，后续元素不可加入");
        assertFalse(segment.tryAdd(div(1, 1)), "独占元素耗尽剩余宽度，后续元素不可加入");
        assertEquals(1, segment.getContent().size(), "被拒绝的元素不应加入段中");
    }

    @Test
    @DisplayName("独占元素在段非空时被拒绝")
    public void testBlockElementRejectedWhenSegmentNotEmpty() {
        Segment segment = new Segment(100);
        assertTrue(segment.tryAdd(leftFlow(30, 10)), "共享元素可加入空段");

        assertFalse(segment.tryAdd(div(20, 10)), "段非空时独占元素不可加入");
        assertEquals(1, segment.getContent().size(), "段内仍只有 1 个元素");

        // 段仍有剩余空间，共享元素可以继续加入
        Div<Div> another = leftFlow(20, 10);
        assertTrue(segment.tryAdd(another), "段内仍有剩余空间，共享元素可以加入");
        assertEquals(2, segment.getContent().size(), "段内应有 2 个元素");
        assertSame(another, segment.getContent().get(1), "后加入的元素位于内容末尾");
    }

    @Test
    @DisplayName("浮动方向与 Clear 对立时为独占元素（right + clear left）")
    public void testRightFloatWithClearLeftIsBlockElement() {
        Segment segment = new Segment(100);
        Div<Div> block = div(30, 10);
        block.setFloat(AFloat.right).setClear(Clear.left);
        assertTrue(block.isBlockElement(), "right + clear left 为独占元素");

        assertTrue(segment.tryAdd(block), "独占元素可加入空段");
        assertEquals(1, segment.getContent().size(), "段内应含有 1 个元素");
        assertFalse(segment.tryAdd(leftFlow(10, 10)), "独占元素耗尽剩余宽度");
    }

    @Test
    @DisplayName("浮动方向与 Clear 对立时为独占元素（left + clear right）")
    public void testLeftFloatWithClearRightIsBlockElement() {
        Segment segment = new Segment(100);
        Div<Div> block = div(30, 10);
        block.setFloat(AFloat.left).setClear(Clear.right);
        assertTrue(block.isBlockElement(), "left + clear right 为独占元素");

        assertTrue(segment.tryAdd(block), "独占元素可加入空段");
        assertEquals(1, segment.getContent().size(), "段内应含有 1 个元素");
        assertFalse(segment.tryAdd(centerFlow(10, 10)), "独占元素耗尽剩余宽度");
    }

    // ---------------------------------------------------------------
    // 剩余宽度
    // ---------------------------------------------------------------

    @Test
    @DisplayName("刚好用尽剩余宽度时可以加入，之后立即拒绝")
    public void testExactFitThenReject() {
        Segment segment = new Segment(100);

        assertTrue(segment.tryAdd(leftFlow(60, 10)), "60 宽元素可加入 100 宽空段");
        assertTrue(segment.tryAdd(leftFlow(40, 10)), "40 宽元素刚好填满剩余空间");
        assertEquals(2, segment.getContent().size(), "段内应有 2 个元素");

        assertFalse(segment.tryAdd(leftFlow(1, 10)), "剩余宽度为 0，任何元素不可加入");
        assertEquals(2, segment.getContent().size(), "被拒绝的元素不应加入段中");
        assertEquals(2, segment.getSizeList().size(), "被拒绝的元素不应产生尺寸记录");
    }

    @Test
    @DisplayName("元素宽度超过剩余宽度时被拒绝，且不消耗剩余宽度")
    public void testWidthExceedsRemainWidth() {
        Segment segment = new Segment(100);
        assertTrue(segment.tryAdd(leftFlow(70, 10)), "70 宽元素可加入 100 宽空段");

        assertFalse(segment.tryAdd(leftFlow(40, 10)), "40 宽超过剩余 30，应被拒绝");
        assertEquals(1, segment.getContent().size(), "段内仍只有 1 个元素");

        Div<Div> fits = leftFlow(30, 10);
        assertTrue(segment.tryAdd(fits), "被拒绝的元素不消耗空间，30 宽仍可加入");
        assertEquals(2, segment.getContent().size(), "段内应有 2 个元素");
        assertSame(fits, segment.getContent().get(1), "元素位置正确");
    }

    @Test
    @DisplayName("元素宽度大于段宽度时按段宽度裁剪后加入")
    public void testOversizedElementWidthIsClamped() {
        Segment segment = new Segment(100);
        Div<Div> wide = div(250, 10);

        assertTrue(segment.tryAdd(wide), "过宽元素被裁剪后可加入空段");
        assertEquals(1, segment.getContent().size(), "段内应含有 1 个元素");
        assertEquals(100d, segment.getSizeList().get(0).getWidth(), DELTA, "元素宽度被裁剪为段宽度");
        assertEquals(100d, wide.getWidth(), DELTA, "元素自身宽度被重置");
        assertFalse(segment.tryAdd(leftFlow(10, 10)), "段宽度被完全占用");
    }

    @Test
    @DisplayName("内边距与边框计入元素占用宽度")
    public void testPaddingAndBorderCountInWidth() {
        Segment segment = new Segment(100);
        Div<Div> padded = leftFlow(40, 10);
        padded.setPadding(5d);
        padded.setBorder(2d);

        assertTrue(segment.tryAdd(padded), "40 + 2*5 + 2*2 = 54 宽可加入");
        assertEquals(54d, segment.getSizeList().get(0).getWidth(), DELTA, "元素占用宽度含内边距与边框");

        Div<Div> tooWide = leftFlow(40, 10);
        tooWide.setPadding(5d);
        tooWide.setBorder(2d);
        assertFalse(segment.tryAdd(tooWide), "剩余 46 宽不足以容纳 54 宽元素");

        Div<Div> fits = leftFlow(32, 10);
        fits.setPadding(5d);
        fits.setBorder(2d);
        // 32 + 10 + 4 = 46 == 剩余宽度
        assertTrue(segment.tryAdd(fits), "刚好等于剩余宽度的元素可以加入");
        assertEquals(2, segment.getContent().size(), "段内应有 2 个元素");
    }

    @Test
    @DisplayName("段高度取所有元素高度的最大值")
    public void testHeightIsMaxOfElements() {
        Segment segment = new Segment(100);

        assertTrue(segment.tryAdd(leftFlow(20, 50)), "元素可加入");
        assertEquals(50d, segment.getHeight(), DELTA, "段高度为 50");

        assertTrue(segment.tryAdd(leftFlow(20, 10)), "元素可加入");
        assertEquals(50d, segment.getHeight(), DELTA, "较矮元素不降低段高度");

        assertTrue(segment.tryAdd(leftFlow(20, 80)), "元素可加入");
        assertEquals(80d, segment.getHeight(), DELTA, "更高的元素抬高段高度");
        assertEquals(3, segment.getContent().size(), "段内应有 3 个元素");
    }

    // ---------------------------------------------------------------
    // Float / Clear 组合规则（段内不含居中元素）
    // ---------------------------------------------------------------

    @Test
    @DisplayName("段内已有左浮动元素时，left + clear left 元素被拒绝")
    public void testLeftFloatWithClearLeftRejectedWhenLeftExists() {
        Segment segment = new Segment(100);
        assertTrue(segment.tryAdd(leftFlow(30, 10)), "左浮动元素可加入空段");

        Div<Div> blocked = leftFlow(30, 10);
        blocked.setClear(Clear.left);
        assertFalse(segment.tryAdd(blocked), "段内已有左浮动元素，clear left 元素被拒绝");
        assertEquals(1, segment.getContent().size(), "段内仍只有 1 个元素");
        assertEquals(1, segment.getSizeList().size(), "被拒绝的元素不应产生尺寸记录");
    }

    @Test
    @DisplayName("段内没有左浮动元素时，left + clear left 元素可以加入")
    public void testLeftFloatWithClearLeftAcceptedWhenNoLeftExists() {
        Segment segment = new Segment(100);
        assertTrue(segment.tryAdd(rightFlow(30, 10)), "右浮动元素可加入空段");

        Div<Div> newDiv = leftFlow(30, 10);
        newDiv.setClear(Clear.left);
        assertTrue(segment.tryAdd(newDiv), "段内无左浮动元素，clear left 元素可以加入");
        assertEquals(2, segment.getContent().size(), "段内应有 2 个元素");
        assertSame(newDiv, segment.getContent().get(1), "元素位置正确");
    }

    @Test
    @DisplayName("段内已有右浮动元素时，right + clear right 元素被拒绝")
    public void testRightFloatWithClearRightRejectedWhenRightExists() {
        Segment segment = new Segment(100);
        assertTrue(segment.tryAdd(rightFlow(30, 10)), "右浮动元素可加入空段");

        Div<Div> blocked = rightFlow(30, 10);
        blocked.setClear(Clear.right);
        assertFalse(segment.tryAdd(blocked), "段内已有右浮动元素，clear right 元素被拒绝");
        assertEquals(1, segment.getContent().size(), "段内仍只有 1 个元素");
    }

    @Test
    @DisplayName("段内没有右浮动元素时，right + clear right 元素可以加入")
    public void testRightFloatWithClearRightAcceptedWhenNoRightExists() {
        Segment segment = new Segment(100);
        assertTrue(segment.tryAdd(leftFlow(30, 10)), "左浮动元素可加入空段");

        Div<Div> newDiv = rightFlow(30, 10);
        newDiv.setClear(Clear.right);
        assertTrue(segment.tryAdd(newDiv), "段内无右浮动元素，clear right 元素可以加入");
        assertEquals(2, segment.getContent().size(), "段内应有 2 个元素");
    }

    @Test
    @DisplayName("段内不含居中元素时，居中元素不能加入")
    public void testCenterRejectedInNonCenterSegment() {
        Segment segment = new Segment(100);
        assertTrue(segment.tryAdd(leftFlow(30, 10)), "左浮动元素可加入空段");

        assertFalse(segment.tryAdd(centerFlow(30, 10)), "段内已含非居中元素，居中元素被拒绝");
        assertFalse(segment.isCenterFloat(), "段不是居中布局");
        assertEquals(1, segment.getContent().size(), "段内仍只有 1 个元素");

        Div<Div> accepted = leftFlow(30, 10);
        assertTrue(segment.tryAdd(accepted), "共享元素可以继续加入");
        assertEquals(2, segment.getContent().size(), "段内应有 2 个元素");
    }

    // ---------------------------------------------------------------
    // Float / Clear 组合规则（段内含居中元素）
    // ---------------------------------------------------------------

    @Test
    @DisplayName("居中段内可以继续加入居中元素")
    public void testCenterSegmentAcceptsCenterElements() {
        Segment segment = new Segment(100);
        assertTrue(segment.tryAdd(centerFlow(30, 10)), "居中元素可加入空段");
        assertTrue(segment.isCenterFloat(), "段为居中布局");

        Div<Div> second = centerFlow(30, 10);
        assertTrue(segment.tryAdd(second), "居中元素可以继续加入居中段");
        assertEquals(2, segment.getContent().size(), "段内应有 2 个元素");
        assertSame(second, segment.getContent().get(1), "元素位置正确");
        assertEquals(10d, segment.getHeight(), DELTA, "段高度为元素高度");
    }

    @Test
    @DisplayName("居中段内拒绝非居中元素")
    public void testCenterSegmentRejectsNonCenterElement() {
        Segment segment = new Segment(100);
        assertTrue(segment.tryAdd(centerFlow(30, 10)), "居中元素可加入空段");

        assertFalse(segment.tryAdd(leftFlow(30, 10)), "居中段内拒绝左浮动元素");
        assertEquals(1, segment.getContent().size(), "段内仍只有 1 个元素");

        assertFalse(segment.tryAdd(rightFlow(20, 10)), "居中段内拒绝右浮动元素");
        assertEquals(1, segment.getContent().size(), "段内仍只有 1 个元素");
    }

    @Test
    @DisplayName("居中段内拒绝 clear left 的居中元素")
    public void testCenterSegmentRejectsClearLeftElement() {
        Segment segment = new Segment(100);
        assertTrue(segment.tryAdd(centerFlow(30, 10)), "居中元素可加入空段");

        Div<Div> clearLeft = centerFlow(30, 10);
        clearLeft.setClear(Clear.left);
        assertFalse(segment.tryAdd(clearLeft), "居中段内拒绝 clear left 元素");
        assertEquals(1, segment.getContent().size(), "段内仍只有 1 个元素");
    }

    @Test
    @DisplayName("居中段内最后一个元素 clear right 时拒绝新元素")
    public void testCenterSegmentRejectsWhenLastElementClearsRight() {
        Segment segment = new Segment(100);
        Div<Div> first = centerFlow(30, 10);
        first.setClear(Clear.right);
        assertTrue(segment.tryAdd(first), "空段直接加入居中的 clear right 元素");

        assertFalse(segment.tryAdd(centerFlow(30, 10)), "最后一个元素 clear right 时拒绝新元素");
        assertEquals(1, segment.getContent().size(), "段内仍只有 1 个元素");
        assertEquals(Clear.right, segment.getContent().get(0).getClear(), "段内元素 Clear 未被改变");
    }

    // ---------------------------------------------------------------
    // 其他可观察的副作用
    // ---------------------------------------------------------------

    @Test
    @DisplayName("加入不可拆分元素时段标记为可拆分")
    public void testBlockableFlagUpdatedByAdd() {
        Segment splittable = new Segment(100);
        Div<Div> d1 = div(30, 10);
        d1.setIntegrity(false);
        assertTrue(splittable.tryAdd(d1), "元素可加入");
        assertTrue(splittable.isBlockable(), "出现可拆分元素后段可拆分");

        Segment solid = new Segment(100);
        Div<Div> d2 = div(30, 10);
        d2.setIntegrity(true);
        assertTrue(solid.tryAdd(d2), "元素可加入");
        assertFalse(solid.isBlockable(), "只有一个不可拆分元素时段不可拆分");
    }

    @Test
    @DisplayName("加入页面剩余空间填充元素后段被标记为填充段")
    public void testRemainAreaFillerFlag() {
        Segment segment = new Segment(100);
        PageAreaFiller filler = new PageAreaFiller();

        assertTrue(segment.tryAdd(filler), "填充元素可加入空段");
        assertTrue(segment.isRemainAreaFiller(), "段被标记为剩余空间填充段");
        assertEquals(1, segment.getContent().size(), "段内应含有 1 个元素");
        assertSame(filler, segment.getContent().get(0), "段内元素应为填充元素");
    }

    @Test
    @DisplayName("尺寸未确定的元素按 0 宽处理并被独占加入空段")
    public void testUnSizedBlockElement() {
        Segment segment = new Segment(100);
        Div<Div> unknown = new Div<Div>();
        assertTrue(unknown.isBlockElement(), "默认 Div 为独占元素");

        assertTrue(segment.tryAdd(unknown), "尺寸未确定的独占元素可加入空段");
        assertEquals(1, segment.getContent().size(), "段内应含有 1 个元素");
        assertEquals(0d, segment.getSizeList().get(0).getWidth(), DELTA, "尺寸按 0 记录");
        assertFalse(segment.tryAdd(leftFlow(10, 10)), "独占元素仍占用整段，后续元素不可加入");
    }

    @Test
    @DisplayName("多个元素尺寸序列与内容序列一一对应")
    public void testSizeListMatchesContent() {
        Segment segment = new Segment(120);
        Div<Div> a = leftFlow(20, 10);
        Div<Div> b = rightFlow(30, 25);
        Div<Div> c = leftFlow(40, 5);

        assertTrue(segment.tryAdd(a), "元素 a 可加入");
        assertTrue(segment.tryAdd(b), "元素 b 可加入");
        assertTrue(segment.tryAdd(c), "元素 c 可加入");

        List<Div> content = segment.getContent();
        List<Rectangle> sizes = segment.getSizeList();
        assertEquals(3, content.size(), "段内应有 3 个元素");
        assertEquals(3, sizes.size(), "尺寸序列应有 3 个矩形");
        assertSame(a, content.get(0), "内容顺序与加入顺序一致");
        assertSame(b, content.get(1), "内容顺序与加入顺序一致");
        assertSame(c, content.get(2), "内容顺序与加入顺序一致");
        assertEquals(20d, sizes.get(0).getWidth(), DELTA, "尺寸 a 宽度");
        assertEquals(30d, sizes.get(1).getWidth(), DELTA, "尺寸 b 宽度");
        assertEquals(40d, sizes.get(2).getWidth(), DELTA, "尺寸 c 宽度");
        assertEquals(25d, segment.getHeight(), DELTA, "段高度为最大元素高度");

        assertFalse(segment.tryAdd(leftFlow(40, 10)), "剩余 30 宽不足以容纳 40 宽元素");
        assertEquals(3, content.size(), "被拒绝的元素不进入内容序列");
        assertEquals(3, sizes.size(), "被拒绝的元素不进入尺寸序列");
    }
}
