package org.ofdrw.layout.engine;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.ofdrw.layout.Rectangle;
import org.ofdrw.layout.element.AFloat;
import org.ofdrw.layout.element.Clear;
import org.ofdrw.layout.element.Div;
import org.ofdrw.layout.element.PageAreaFiller;

import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * {@link Segment#tryAdd(Div)} 单元测试。
 * <p>
 * 只通过公开（或同包可见）的段状态断言行为：内容、尺寸序列、段宽、段高、
 * 是否可拆分以及是否为剩余空间填充段。
 *
 * @author test
 */
public class SegmentTryAddTests {

    private static final double DELTA = 1e-9;

    /**
     * 构造一个指定宽高的普通 Div（默认 Float=left，Clear=both，即独占元素）
     */
    private static Div<Div> div(double width, double height) {
        return new Div<Div>(width, height);
    }

    /**
     * 构造一个非独占（共享）元素：左浮动且不清理两侧
     */
    private static Div<Div> leftFlow(double width, double height) {
        Div<Div> d = div(width, height);
        d.setFloat(AFloat.left);
        d.setClear(Clear.none);
        return d;
    }

    /**
     * 构造一个非独占（共享）元素：右浮动且不清理两侧
     */
    private static Div<Div> rightFlow(double width, double height) {
        Div<Div> d = div(width, height);
        d.setFloat(AFloat.right);
        d.setClear(Clear.none);
        return d;
    }

    /**
     * 构造一个非独占（共享）元素：居中浮动且不清理两侧
     */
    private static Div<Div> centerFlow(double width, double height) {
        Div<Div> d = div(width, height);
        d.setFloat(AFloat.center);
        d.setClear(Clear.none);
        return d;
    }

    // ---------------------------------------------------------------
    // null 入参
    // ---------------------------------------------------------------

    @Test
    @DisplayName("tryAdd(null) 返回 true 且不改变空段状态")
    public void testNullIntoEmptySegment() {
        Segment segment = new Segment(100);

        assertTrue(segment.tryAdd(null), "null 元素被视为加入成功");

        assertTrue(segment.isEmpty(), "段应仍为空");
        assertEquals(0, segment.getContent().size(), "内容列表不应有元素");
        assertEquals(0, segment.getSizeList().size(), "尺寸列表不应有元素");
        assertEquals(0d, segment.getHeight(), DELTA, "空段高度为 0");
        assertEquals(100d, segment.getWidth(), DELTA, "段宽度不应变化");
        assertFalse(segment.isBlockable(), "空段默认不可拆分");
        assertFalse(segment.isRemainAreaFiller(), "空段不是剩余空间填充段");
    }

    @Test
    @DisplayName("空间耗尽后 tryAdd(null) 依然返回 true（null 检查最先执行）")
    public void testNullAfterSpaceExhausted() {
        Segment segment = new Segment(100);
        Div<Div> block = div(40, 20);

        assertTrue(segment.tryAdd(block), "独占元素应可加入空段");
        assertTrue(segment.tryAdd(null), "null 元素应直接返回 true");
        assertEquals(1, segment.getContent().size(), "内容列表仍只有 1 个元素");
        assertFalse(segment.tryAdd(div(10, 10)), "空间已耗尽，普通元素不可加入");
    }

    // ---------------------------------------------------------------
    // 独占（块级）元素
    // ---------------------------------------------------------------

    @Test
    @DisplayName("独占元素加入空段：占用整段宽度，反复加入被拒绝")
    public void testBlockElementOccupiesWholeSegment() {
        Segment segment = new Segment(100);
        Div<Div> block = div(40, 20);
        assertTrue(block.isBlockElement(), "默认 Div 为独占元素");

        assertTrue(segment.tryAdd(block), "独占元素可加入空段");

