 * 绝对定位默认不为块级元素
 *
 * @return true 独占; false 共享
 */
public boolean isBlockElement() {
    if (position == Position.Absolute) {
        return false;
    }
    /*
     独占段的元素类型
     1. 独占
     2. 浮动 + Clear 对立
     */
    return (clear == Clear.both)
            || (aFloat == AFloat.right && clear == Clear.left)
            || (aFloat == AFloat.left && clear == Clear.right);
}

