package org.ofdrw.layout.engine.render;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.ofdrw.core.basicStructure.pageObj.layer.PageBlockType;
import org.ofdrw.core.basicStructure.pageObj.layer.block.CT_PageBlock;
import org.ofdrw.core.basicStructure.pageObj.layer.block.PathObject;
import org.ofdrw.core.basicType.ST_Box;
import org.ofdrw.core.graph.pathObj.AbbreviatedData;
import org.ofdrw.core.graph.pathObj.OptVal;
import org.ofdrw.layout.element.Div;

import java.util.ArrayList;
import java.util.LinkedList;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * {@link DivRender#render(CT_PageBlock, Div, AtomicInteger)} 的单元测试。
 * <p>
 * 覆盖：绘制入口的前置条件（无背景无边框直接返回、高度必须指定）、背景绘制、
 * 等宽边框绘制、不等宽边框逐边绘制、透明度、边框颜色、虚线样式、以及最大图元ID的自增行为。
 */
@DisplayName("Div 盒式模型渲染器测试")
public class DivRenderRenderTests {

    private static final double DELTA = 1e-6;

    /* ------------------------------------------------------------------ 工具方法 */

    private static CT_PageBlock newLayer() {
        return new CT_PageBlock();
    }

    /**
     * 创建一个指定位置与尺寸的 Div
     */
    private static Div<?> div(double x, double y, double width, double height) {
        Div<?> d = new Div();
        d.setX(x);
        d.setY(y);
        d.setWidth(width);
        d.setHeight(height);
        return d;
    }

    /**
     * 把图层内容全部取出并断言都是 PathObject
     */
    @SuppressWarnings("unchecked")
    private static List<PathObject> paths(CT_PageBlock layer) {
        List<PathObject> res = new ArrayList<>();
        for (PageBlockType pb : layer.getPageBlocks()) {
            assertNotNull(pb, "图层中不应出现无法识别的页块元素");
            assertTrue(pb instanceof PathObject,
                    "Div 渲染只会产生 PathObject，实际为: " + pb.getClass().getName());
            res.add((PathObject) pb);
        }
        return res;
    }

    private static void assertBoundary(PathObject p, double x, double y, double w, double h) {
        ST_Box b = p.getBoundary();
        assertNotNull(b, "图元必须设置外接矩形");
        assertEquals(x, b.getTopLeftX(), DELTA, "外接矩形左上角X");
        assertEquals(y, b.getTopLeftY(), DELTA, "外接矩形左上角Y");
        assertEquals(w, b.getWidth(), DELTA, "外接矩形宽度");
        assertEquals(h, b.getHeight(), DELTA, "外接矩形高度");
    }

    private static LinkedList<OptVal> ops(PathObject p) {
        AbbreviatedData data = p.getAbbreviatedDataEle();
        assertNotNull(data, "图元必须设置图形轮廓数据");
        return data.getRawOptVal();
    }

    private static void assertRectPath(PathObject p, double x, double y, double w, double h) {
        LinkedList<OptVal> ops = ops(p);
        assertEquals(5, ops.size(), "矩形轮廓应包含 M、3个 L 与 C 共5个操作");
        assertEquals("M", ops.get(0).getOpt());
        assertArrayEquals(new double[]{x, y}, ops.get(0).getValues(), DELTA, "矩形起点");
        assertEquals("L", ops.get(1).getOpt());
        assertArrayEquals(new double[]{x + w, y}, ops.get(1).getValues(), DELTA, "矩形右上角");
        assertEquals("L", ops.get(2).getOpt());
        assertArrayEquals(new double[]{x + w, y + h}, ops.get(2).getValues(), DELTA, "矩形右下角");
        assertEquals("L", ops.get(3).getOpt());
        assertArrayEquals(new double[]{x, y + h}, ops.get(3).getValues(), DELTA, "矩形左下角");
        assertEquals("C", ops.get(4).getOpt());
    }

    private static void assertLinePath(PathObject p, double fromX, double fromY) {
        LinkedList<OptVal> ops = ops(p);
        assertEquals(2, ops.size(), "线条轮廓应包含 M 与 L 共2个操作");
        assertEquals("M", ops.get(0).getOpt());
        assertArrayEquals(new double[]{fromX, fromY}, ops.get(0).getValues(), DELTA, "线条起点");
        assertEquals("L", ops.get(1).getOpt());
        assertArrayEquals(new double[]{fromX, fromY}, ops.get(1).getValues(), DELTA, "线条终点");
    }

    private static String rgb(PathObject p, boolean fill) {
        if (fill) {
            assertNotNull(p.getFillColor(), "应存在填充颜色");
            return p.getFillColor().getValue().toString();
        }
        assertNotNull(p.getStrokeColor(), "应存在描边颜色");
        return p.getStrokeColor().getValue().toString();
    }

    /* ------------------------------------------------------------------ 前置条件 */

    @Test
    @DisplayName("无背景色且无边框：直接返回，不产生图元、不消耗ID")
    void noBackgroundAndNoBorder_skipsRendering() {
        CT_PageBlock layer = newLayer();
        AtomicInteger maxUnitID = new AtomicInteger(100);
        Div<?> e = div(10, 20, 100, 50);

        DivRender.render(layer, e, maxUnitID);

        assertTrue(layer.getPageBlocks().isEmpty(), "无背景无边框的Div不应产生任何图元");
        assertEquals(100, maxUnitID.get(), "未绘制任何图元时不应消耗ID");
    }

    @Test
    @DisplayName("无背景色且无边框：即使高度未指定也不抛异常（先返回）")
    void noBackgroundAndNoBorderWithoutHeight_doesNotThrow() {
        CT_PageBlock layer = newLayer();
        AtomicInteger maxUnitID = new AtomicInteger(7);
        Div<?> e = new Div();
        e.setWidth(100d);

        DivRender.render(layer, e, maxUnitID);

        assertTrue(layer.getPageBlocks().isEmpty());
        assertEquals(7, maxUnitID.get());
    }

    @Test
    @DisplayName("存在背景色但高度为null：抛出IllegalArgumentException且不绘制")
    void nullHeightWithBackground_throwsIllegalArgumentException() {
        CT_PageBlock layer = newLayer();
        AtomicInteger maxUnitID = new AtomicInteger(1);
        Div<?> e = new Div();
        e.setX(0d);
        e.setY(0d);
        e.setWidth(100d);
        e.setBackgroundColor(255, 0, 0);

        IllegalArgumentException ex = assertThrows(IllegalArgumentException.class,
                () -> DivRender.render(layer, e, maxUnitID));
        assertNotNull(ex.getMessage());
        assertTrue(ex.getMessage().contains("高度"), "异常信息应指明高度必须指定，实际：" + ex.getMessage());
        assertTrue(layer.getPageBlocks().isEmpty(), "高度校验失败时不应绘制任何图元");
        assertEquals(1, maxUnitID.get());
    }

    @Test
    @DisplayName("只有边框且高度为null：同样抛出IllegalArgumentException")
    void nullHeightWithBorder_throwsIllegalArgumentException() {
        CT_PageBlock layer = newLayer();
        AtomicInteger maxUnitID = new AtomicInteger(1);
        Div<?> e = new Div();
        e.setX(0d);
        e.setY(0d);
        e.setWidth(100d);
        e.setBorder(1d);

        assertThrows(IllegalArgumentException.class, () -> DivRender.render(layer, e, maxUnitID));
        assertTrue(layer.getPageBlocks().isEmpty());
        assertEquals(1, maxUnitID.get());
    }

    /* ------------------------------------------------------------------ 背景绘制 */

    @Test
    @DisplayName("仅有背景色、无边框：绘制背景矩形，同时等宽分支绘制零宽边框")
    void backgroundOnly_drawsBackgroundAndZeroWidthBorder() {
        CT_PageBlock layer = newLayer();
        AtomicInteger maxUnitID = new AtomicInteger(0);
        Div<?> e = div(10, 20, 100, 50);
        e.setBackgroundColor(10, 20, 30);

        DivRender.render(layer, e, maxUnitID);

        List<PathObject> blocks = paths(layer);
        assertEquals(2, blocks.size(), "背景 + 等宽分支的边框");

        PathObject bg = blocks.get(0);
        assertBoundary(bg, 10, 20, 100, 50);
        assertRectPath(bg, 0, 0, 100, 50);
        assertEquals(Boolean.FALSE, bg.getStroke(), "背景不描边");
        assertEquals(Boolean.TRUE, bg.getFill(), "背景填充");
        assertEquals("10 20 30", rgb(bg, true), "背景填充颜色应为设置的RGB");
        assertNull(bg.getLineWidth(), "背景不设置线宽");
        assertEquals(Integer.valueOf(255), bg.getAlpha(), "未设置透明度时alpha缺省为255");

        PathObject border = blocks.get(1);
        assertBoundary(border, 10, 20, 100, 50);
        assertEquals(0d, border.getLineWidth(), DELTA, "四边为0时等宽分支的线宽为0");
    }

    @Test
    @DisplayName("背景绘制考虑外边距、内边距与边框宽度")
    void backgroundWithBoxModel_usesExpectedBoundary() {
        CT_PageBlock layer = newLayer();
        AtomicInteger maxUnitID = new AtomicInteger(0);
        Div<?> e = div(10, 20, 100, 50);
        e.setBackgroundColor(10, 20, 30);
        e.setMargin(5d, 6d, 7d, 8d);   // 上 右 下 左
        e.setPadding(1d, 2d, 3d, 4d);  // 上 右 下 左
        e.setBorder(2d);

        DivRender.render(layer, e, maxUnitID);

        List<PathObject> blocks = paths(layer);
        assertEquals(2, blocks.size());

        // x = 10 + marginLeft(8) + borderLeft(2) = 20
        // y = 20 + marginTop(5) + borderTop(2) = 27
        // w = paddingLeft(4) + width(100) + paddingRight(2) = 106
        // h = paddingTop(1) + height(50) + paddingBottom(3) = 54
        PathObject bg = blocks.get(0);
        assertBoundary(bg, 20, 27, 106, 54);
        assertRectPath(bg, 0, 0, 106, 54);
    }

    @Test
    @DisplayName("内容高度为0时不绘制背景，但边框仍然绘制")
    void zeroContentHeight_skipsBackground() {
        CT_PageBlock layer = newLayer();
        AtomicInteger maxUnitID = new AtomicInteger(0);
        Div<?> e = div(0, 0, 100, 0);
        e.setBackgroundColor(200, 200, 200);

        DivRender.render(layer, e, maxUnitID);

        List<PathObject> blocks = paths(layer);
        assertEquals(1, blocks.size(), "内容高度为0时不绘制背景，只绘制边框");
        PathObject border = blocks.get(0);
        assertNull(border.getFillColor(), "仅边框的图元没有填充色");
        assertEquals(0d, border.getLineWidth(), DELTA);
    }

    @Test
    @DisplayName("缺少X坐标时无法计算位置：抛出NullPointerException")
    void missingCoordinate_throwsNullPointerException() {
        CT_PageBlock layer = newLayer();
        AtomicInteger maxUnitID = new AtomicInteger(0);
        Div<?> e = new Div();
        e.setY(0d);
        e.setWidth(100d);
        e.setHeight(50d);
        e.setBackgroundColor(1, 2, 3);

        assertThrows(NullPointerException.class, () -> DivRender.render(layer, e, maxUnitID));
        assertTrue(layer.getPageBlocks().isEmpty());
    }

    /* ------------------------------------------------------------------ 等宽边框 */

    @Test
    @DisplayName("等宽边框：绘制单个边框矩形，边界与线宽符合盒式模型")
    void uniformBorder_drawsSingleBorderRect() {
        CT_PageBlock layer = newLayer();
        AtomicInteger maxUnitID = new AtomicInteger(0);
        Div<?> e = div(10, 20, 100, 50);
        e.setPadding(1d, 2d, 3d, 4d);
        e.setMargin(5d, 6d, 7d, 8d);
        e.setBorder(2d);

        DivRender.render(layer, e, maxUnitID);

        List<PathObject> blocks = paths(layer);
        assertEquals(1, blocks.size(), "四边宽度一致时只绘制1个边框图元");
        PathObject border = blocks.get(0);
        // x = 10 + 8 = 18, y = 20 + 5 = 25
        // w = 2 + 4 + 100 + 2 + 2 = 110, h = 2 + 1 + 50 + 3 + 2 = 58
        assertBoundary(border, 18, 25, 110, 58);
        assertEquals(2d, border.getLineWidth(), DELTA, "线宽为边框宽度");
        assertRectPath(border, 1, 1, 108, 56);
        assertNull(border.getStrokeColor(), "未设置边框颜色时使用默认黑色（无颜色元素）");
        assertNull(border.getFillColor(), "边框图元不填充");
        assertEquals(Integer.valueOf(255), border.getAlpha());
    }

    @Test
    @DisplayName("等宽边框：设置边框颜色后写入描边颜色")
    void uniformBorder_withColor_setsStrokeColor() {
        CT_PageBlock layer = newLayer();
        AtomicInteger maxUnitID = new AtomicInteger(0);
        Div<?> e = div(0, 0, 80, 40);
        e.setBorder(3d);
        e.setBorderColor(255, 128, 0);

        DivRender.render(layer, e, maxUnitID);

        List<PathObject> blocks = paths(layer);
        assertEquals(1, blocks.size());
        assertEquals("255 128 0", rgb(blocks.get(0), false));
    }

    @Test
    @DisplayName("等宽边框：宽度差异小于0.001时仍视为等宽（STBase.fmt精度）")
    void nearEqualBorders_treatedAsUniform() {
        CT_PageBlock layer = newLayer();
        AtomicInteger maxUnitID = new AtomicInteger(0);
        Div<?> e = div(0, 0, 100, 50);
        e.setBorderTop(2.0001);
        e.setBorderRight(2.0002);
        e.setBorderBottom(2.0003);
        e.setBorderLeft(2.0004);

        DivRender.render(layer, e, maxUnitID);

        List<PathObject> blocks = paths(layer);
        assertEquals(1, blocks.size(), "格式化后相等的边框宽度按等宽处理");
        assertEquals(2.0001, blocks.get(0).getLineWidth(), 1e-9, "等宽分支使用上边框宽度作为线宽");
    }

    /* ------------------------------------------------------------------ 透明度 */

    @Test
    @DisplayName("透明度：0.5转换为127，并同时作用于背景与边框")
    void opacity_appliedAsAlpha() {
        CT_PageBlock layer = newLayer();
        AtomicInteger maxUnitID = new AtomicInteger(0);
        Div<?> e = div(0, 0, 100, 50);
        e.setBackgroundColor(1, 2, 3);
        e.setBorder(2d);
        e.setOpacity(0.5);

        DivRender.render(layer, e, maxUnitID);

        List<PathObject> blocks = paths(layer);
        assertEquals(2, blocks.size());
        assertEquals(Integer.valueOf(127), blocks.get(0).getAlpha(), "0.5 * 255 = 127.5 取整为127");
        assertEquals(Integer.valueOf(127), blocks.get(1).getAlpha());
    }

    @Test
    @DisplayName("透明度边界值：0 -> alpha 0，1 -> alpha 255")
    void opacityBoundaries_appliedAsAlpha() {
        CT_PageBlock layer = newLayer();
        Div<?> transparent = div(0, 0, 100, 50);
        transparent.setBorder(1d);
        transparent.setOpacity(0d);
        DivRender.render(layer, transparent, new AtomicInteger(0));

        CT_PageBlock opaqueLayer = newLayer();
        Div<?> opaque = div(0, 0, 100, 50);
        opaque.setBorder(1d);
        opaque.setOpacity(1d);
        DivRender.render(opaqueLayer, opaque, new AtomicInteger(0));

        assertEquals(Integer.valueOf(0), paths(layer).get(0).getAlpha());
        assertEquals(Integer.valueOf(255), paths(opaqueLayer).get(0).getAlpha());
    }

    /* ------------------------------------------------------------------ 虚线 */

    @Test
    @DisplayName("单参数虚线：虚线与空白等长，且不设置偏移量")
    void singleValueDash_setsPatternWithoutOffset() {
        CT_PageBlock layer = newLayer();
        AtomicInteger maxUnitID = new AtomicInteger(0);
        Div<?> e = div(0, 0, 100, 50);
        e.setBorder(1d);
        e.setBorderDash(3d);

        DivRender.render(layer, e, maxUnitID);

        PathObject border = paths(layer).get(0);
        assertNotNull(border.getDashPattern(), "应设置虚线样式");
        assertEquals("3 3", border.getDashPattern().toString());
        assertEquals(0d, border.getDashOffset(), DELTA, "偏移量为0时不下发DashOffset");
    }

    @Test
    @DisplayName("带偏移量的虚线：写入DashOffset与DashPattern")
    void dashWithOffset_setsOffsetAndPattern() {
        CT_PageBlock layer = newLayer();
        AtomicInteger maxUnitID = new AtomicInteger(0);
        Div<?> e = div(0, 0, 100, 50);
        e.setBorder(1d);
        e.setBorderDash(1d, 3d, 2d);

        DivRender.render(layer, e, maxUnitID);

        PathObject border = paths(layer).get(0);
        assertEquals(1d, border.getDashOffset(), DELTA);
        assertEquals("3 2", border.getDashPattern().toString());
    }

    @Test
    @DisplayName("未设置虚线时不写入虚线相关属性")
    void noDash_noDashAttributes() {
        CT_PageBlock layer = newLayer();
        Div<?> e = div(0, 0, 100, 50);
        e.setBorder(1d);

        DivRender.render(layer, e, new AtomicInteger(0));

        PathObject border = paths(layer).get(0);
        assertNull(border.getDashPattern(), "未设置虚线时不应有DashPattern");
    }

    /* ------------------------------------------------------------------ 不等宽边框 */

    @Test
    @DisplayName("不等宽边框：按 上、下、左、右 顺序分别绘制4条边")
    void nonUniformBorders_drawsFourEdgesInOrder() {
        CT_PageBlock layer = newLayer();
        AtomicInteger maxUnitID = new AtomicInteger(0);
        Div<?> e = div(10, 20, 100, 50);
        e.setBorder(2d, 4d, 6d, 8d); // 上 右 下 左
        e.setBorderColor(0, 0, 255);

        DivRender.render(layer, e, maxUnitID);

        List<PathObject> blocks = paths(layer);
        assertEquals(4, blocks.size(), "不等宽边框逐边绘制，共4个图元");

        PathObject top = blocks.get(0);
        assertBoundary(top, 10, 20, 112, 2);
        assertEquals(2d, top.getLineWidth(), DELTA);
        assertLinePath(top, 0, 1);
        assertEquals("0 0 255", rgb(top, false));

        PathObject bottom = blocks.get(1);
        // y = 20 + 0 + 2 + 0 + 50 + 0 = 72
        assertBoundary(bottom, 10, 72, 112, 6);
        assertEquals(6d, bottom.getLineWidth(), DELTA);
        assertLinePath(bottom, 0, 3);

        PathObject left = blocks.get(2);
        // y = 20 + 0 + topWidth(2) = 22；h = 2 + 0 + 50 + 0 + 6 - 2 - 6 = 50
        assertBoundary(left, 10, 22, 8, 50);
        assertEquals(8d, left.getLineWidth(), DELTA);
        assertLinePath(left, 4, 0);

        PathObject right = blocks.get(3);
        // x = 10 + 0 + 8 + 0 + 100 + 0 = 118
        assertBoundary(right, 118, 22, 4, 50);
        assertEquals(4d, right.getLineWidth(), DELTA);
        assertLinePath(right, 2, 0);
    }

    @Test
    @DisplayName("不等宽边框：宽度为0的边被跳过")
    void nonUniformBorders_skipsZeroWidthEdges() {
        CT_PageBlock layer = newLayer();
        AtomicInteger maxUnitID = new AtomicInteger(0);
        Div<?> e = div(0, 0, 100, 50);
        e.setBorder(0d, 4d, 0d, 8d); // 上、下无边框

        DivRender.render(layer, e, maxUnitID);

        List<PathObject> blocks = paths(layer);
        assertEquals(2, blocks.size(), "只绘制左边与右边");
        assertEquals(8d, blocks.get(0).getLineWidth(), DELTA, "先绘制左边");
        assertEquals(4d, blocks.get(1).getLineWidth(), DELTA, "再绘制右边");
        assertBoundary(blocks.get(0), 0, 0, 8, 50);
        assertBoundary(blocks.get(1), 108, 0, 4, 50);
    }

    @Test
    @DisplayName("不等宽边框：内容高度与上下边框都为0时视为占位符，跳过左右边绘制")
    void zeroContentAndNoVerticalBorders_skipsAllEdges() {
        CT_PageBlock layer = newLayer();
        AtomicInteger maxUnitID = new AtomicInteger(30);
        Div<?> e = div(0, 0, 100, 0);
        e.setBorder(0d, 4d, 0d, 8d);

        DivRender.render(layer, e, maxUnitID);

        assertTrue(layer.getPageBlocks().isEmpty(), "占位符元素不应绘制任何图元");
        assertEquals(30, maxUnitID.get(), "占位符不消耗图元ID");
    }

    @Test
    @DisplayName("不等宽边框：透明度与虚线同样作用于各条边")
    void nonUniformBorders_applyAlphaAndDash() {
        CT_PageBlock layer = newLayer();
        AtomicInteger maxUnitID = new AtomicInteger(0);
        Div<?> e = div(0, 0, 100, 50);
        e.setBorder(1d, 2d, 3d, 4d);
        e.setOpacity(1d);
        e.setBorderDash(2d, 1d);

        DivRender.render(layer, e, maxUnitID);

        List<PathObject> blocks = paths(layer);
        assertEquals(4, blocks.size());
        for (PathObject p : blocks) {
            assertEquals(Integer.valueOf(255), p.getAlpha(), "透明度 1.0 对应 alpha 255");
            assertNotNull(p.getDashPattern(), "每条边都应设置虚线样式");
            assertEquals("2 1", p.getDashPattern().toString());
        }
    }

    /* ------------------------------------------------------------------ 图元ID */

    @Test
    @DisplayName("图元ID：按绘制顺序自增，最终写入PathObject与计数器")
    void maxUnitID_incrementedPerDrawnUnit() {
        CT_PageBlock layer = newLayer();
        AtomicInteger maxUnitID = new AtomicInteger(40);
        Div<?> e = div(0, 0, 100, 50);
        e.setBackgroundColor(1, 1, 1);
        e.setBorder(2d);

        DivRender.render(layer, e, maxUnitID);

        List<PathObject> blocks = paths(layer);
        assertEquals(2, blocks.size());
        assertNotNull(blocks.get(0).getID());
        assertNotNull(blocks.get(1).getID());
        assertEquals(Long.valueOf(41L), blocks.get(0).getID().getId(), "背景使用第1个新ID");
        assertEquals(Long.valueOf(42L), blocks.get(1).getID().getId(), "边框使用第2个新ID");
        assertEquals(42, maxUnitID.get(), "计数器应推进到最后一个分配的ID");
        assertFalse(blocks.get(0).getID().getId().equals(blocks.get(1).getID().getId()),
                "不同图元的ID必须不同");
    }

    @Test
    @DisplayName("图元ID：不等宽边框逐边分配ID")
    void maxUnitID_incrementedPerEdge() {
        CT_PageBlock layer = newLayer();
        AtomicInteger maxUnitID = new AtomicInteger(0);
        Div<?> e = div(0, 0, 100, 50);
        e.setBorder(1d, 2d, 3d, 4d);

        DivRender.render(layer, e, maxUnitID);

        List<PathObject> blocks = paths(layer);
        assertEquals(4, blocks.size());
        for (int i = 0; i < blocks.size(); i++) {
            assertEquals(Long.valueOf((long) (i + 1)), blocks.get(i).getID().getId(),
                    "第" + (i + 1) + "个图元的ID应为" + (i + 1));
        }
        assertEquals(4, maxUnitID.get());
    }
