 *
 * @param fileName 图片文件名称
 * @return 图片格式字符串
 */
private String pictureFormat(String fileName) {
    String fileSuffix = fileName.substring(fileName.lastIndexOf(".") + 1).toUpperCase();
    switch (fileSuffix) {
        case "JPG":
            return "JPEG";
        case "TIF":
            return "TIFF";
        default:
            return fileSuffix;
    }
