    @Test
    @DisplayName("字体资源加入失败时抛出RenderException并保留原因")
    void render_fontRegistrationFails_throwsRenderException() {
        ResManager failing = new ResManager(ofdDir, docDir, new AtomicInteger(100)) {
            @Override
            public ST_ID addFont(Font font) throws IOException {
                throw new IOException("字体文件不可读");
            }
        };
        Paragraph paragraph = new Paragraph().setWidth(50d);
        paragraph.add(new Span(font, FONT_SIZE, "A"));

        RenderException ex = assertThrows(RenderException.class,
                () -> ParagraphRender.render(layer, failing, paragraph, new AtomicInteger(100)));

        assertTrue(ex.getMessage().contains("字体复制失败"), "异常信息应说明字体复制失败：" + ex.getMessage());
        assertTrue(ex.getCause() instanceof IOException, "原始IOException应作为原因保留");
        assertTrue(layer.getPageBlocks().isEmpty(), "渲染异常时不应写入不完整的图元");
    }

    // ------------------------------------------------------------------
    // 辅助方法
    // ------------------------------------------------------------------

    /**
     * 构造一个所有可打印ASCII字符宽度占比均为 1 的字体。
     * <p>
     * 该字体没有字体文件，字符宽度 = 字号 * 占比，因此与系统字体无关，结果确定。
     *
     * @param name 字体名称
     * @return 测试字体
     */
    private static Font uniformWidthFont(String name) {
        double[] map = new double[95];
        for (int i = 0; i < map.length; i++) {
            map[i] = 1.0d;
        }
        return new Font(name, name, null, map);
    }

    /**
     * 渲染只包含一个 "AB" Span 的段落，并返回首字符的X坐标
     *
     * @param align 对齐方式
     * @return 首字符X坐标
     */
    private double renderedTextX(TextAlign align) {
        CT_PageBlock block = new CT_PageBlock();
        Paragraph paragraph = new Paragraph().setWidth(50d);
        paragraph.setTextAlign(align);
        paragraph.add(new Span(font, FONT_SIZE, "AB"));

        ParagraphRender.render(block, resManager, paragraph, new AtomicInteger(100));

        List<TextObject> texts = textObjects(block);
        assertEquals(1, texts.size(), "对齐测试应只产生一个文字对象");
        return texts.get(0).getBoundary().getTopLeftX();
    }

    /**
     * 渲染一个宽度25、内容为"AAAAA"（每行2字符）的段落
     *
     * @param height 段落高度，null表示不显式设置
     * @return 渲染出的文字对象
     */
    private List<TextObject> renderWrappedParagraph(Double height) {
        CT_PageBlock block = new CT_PageBlock();
        Paragraph paragraph = new Paragraph().setWidth(25d);
        if (height != null) {
            paragraph.setHeight(height);
        }
        paragraph.add(new Span(font, FONT_SIZE, "AAAAA"));

        maxUnitID = new AtomicInteger(100);
        resManager = new ResManager(ofdDir, docDir, maxUnitID);
        ParagraphRender.render(block, resManager, paragraph, maxUnitID);
        return textObjects(block);
    }

    /**
     * 从图层中取出所有文字对象（按加入顺序）
     *
     * @param block 图层
     * @return 文字对象列表
     */
    private static List<TextObject> textObjects(CT_PageBlock block) {
        List<TextObject> res = new ArrayList<>();
        for (PageBlockType pb : block.getPageBlocks()) {
            if (pb instanceof TextObject) {
                res.add((TextObject) pb);
            }
        }
        return res;
    }
