package org.ofdrw.reader;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.ofdrw.core.basicType.ST_Array;
import org.ofdrw.core.basicType.ST_ID;
import org.ofdrw.core.basicType.ST_RefID;
import org.ofdrw.core.pageDescription.color.color.CT_Color;
import org.ofdrw.core.pageDescription.drawParam.CT_DrawParam;
import org.ofdrw.core.pageDescription.drawParam.LineCapType;
import org.ofdrw.core.pageDescription.drawParam.LineJoinType;

import sun.misc.Unsafe;

import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNotSame;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Unit tests for {@link ResourceManage#superDrawParam(CT_DrawParam, List)}.
 *
 * <p>The production method only depends on the private {@code drawParamMap} field, so the
 * {@link ResourceManage} instance used in these tests is allocated without invoking the
 * constructor (which would require a real OFD document) and the map is injected directly.
 */
public class ResourceManageSuperDrawParamTests {

    private static final Unsafe UNSAFE;
    private static final long DRAW_PARAM_MAP_OFFSET;

    static {
        try {
            Field theUnsafe = Unsafe.class.getDeclaredField("theUnsafe");
            theUnsafe.setAccessible(true);
            UNSAFE = (Unsafe) theUnsafe.get(null);
            Field mapField = ResourceManage.class.getDeclaredField("drawParamMap");
            mapField.setAccessible(true);
            DRAW_PARAM_MAP_OFFSET = UNSAFE.objectFieldOffset(mapField);
        } catch (ReflectiveOperationException e) {
            throw new ExceptionInInitializerError(e);
        }
    }

    private Map<String, CT_DrawParam> drawParamMap;
    private ResourceManage resourceManage;

    @BeforeEach
    void setUp() {
        drawParamMap = new HashMap<>();
        resourceManage = (ResourceManage) UNSAFE.allocateInstance(ResourceManage.class);
        UNSAFE.putObject(resourceManage, DRAW_PARAM_MAP_OFFSET, drawParamMap);
    }

    // ---------------------------------------------------------------------
    // helpers
    // ---------------------------------------------------------------------

    /** Creates a draw param with the given id (and optional relative) and registers it as a resource. */
    private CT_DrawParam registerParam(long id, Long relative) {
        CT_DrawParam param = new CT_DrawParam();
        param.setID(new ST_ID(id));
        if (relative != null) {
            param.setRelative(new ST_RefID(relative));
        }
        drawParamMap.put(String.valueOf(id), param);
        return param;
    }

    /** Creates a draw param without an id and without registering it. */
    private static CT_DrawParam unregisteredParam(Long relative) {
        CT_DrawParam param = new CT_DrawParam();
        if (relative != null) {
            param.setRelative(new ST_RefID(relative));
        }
        return param;
    }

    private static CT_DrawParam paramWithId(long id, Long relative) {
        CT_DrawParam param = new CT_DrawParam();
        param.setID(new ST_ID(id));
        if (relative != null) {
            param.setRelative(new ST_RefID(relative));
        }
        return param;
    }

    private static void fillWithAllAttributes(CT_DrawParam param) {
        param.setLineWidth(2.5);
        param.setJoin(LineJoinType.Bevel);
        param.setCap(LineCapType.Round);
        param.setDashOffset(1.25);
        param.setDashPattern(new ST_Array(4d, 2d));
        param.setMiterLimit(7.5);
        param.setFillColor(CT_Color.rgb(10, 20, 30));
        param.setStrokeColor(CT_Color.rgb(40, 50, 60));
    }

    private static void assertHasAllAttributesOf(CT_DrawParam expected, CT_DrawParam actual) {
        assertEquals(expected.attributeValue("LineWidth"), actual.attributeValue("LineWidth"));
        assertEquals(expected.attributeValue("Join"), actual.attributeValue("Join"));
        assertEquals(expected.attributeValue("Cap"), actual.attributeValue("Cap"));
        assertEquals(expected.attributeValue("DashOffset"), actual.attributeValue("DashOffset"));
        assertEquals(expected.attributeValue("DashPattern"), actual.attributeValue("DashPattern"));
        assertEquals(expected.attributeValue("MiterLimit"), actual.attributeValue("MiterLimit"));
        assertNotNull(actual.getFillColor());
        assertEquals(expected.getFillColor().attributeValue("Value"),
                actual.getFillColor().attributeValue("Value"));
        assertNotNull(actual.getStrokeColor());
        assertEquals(expected.getStrokeColor().attributeValue("Value"),
                actual.getStrokeColor().attributeValue("Value"));
    }

    // ---------------------------------------------------------------------
    // null / trivial inputs
    // ---------------------------------------------------------------------

    @Test
    @DisplayName("null current returns null and does not touch the visited path")
    void nullCurrentReturnsNull() {
        List<String> visited = new ArrayList<>(Collections.singletonList("keep"));

        CT_DrawParam result = resourceManage.superDrawParam(null, visited);

        assertNull(result);
        assertEquals(Collections.singletonList("keep"), visited);
    }

    @Test
    @DisplayName("current without Relative is returned as an independent copy")
    void noRelativeReturnsClone() {
        CT_DrawParam current = paramWithId(1L, null);
        current.setLineWidth(1.5);

        CT_DrawParam result = resourceManage.superDrawParam(current, new ArrayList<>());

        assertNotNull(result);
        assertNotSame(current, result);
        assertNull(result.getRelative());
        assertEquals(current.attributeValue("LineWidth"), result.attributeValue("LineWidth"));
    }

    @Test
    @DisplayName("a null visited list is tolerated when no Relative is present")
    void nullVisitedWithNoRelativeIsAccepted() {
        CT_DrawParam current = paramWithId(1L, null);
        current.setLineWidth(1.5);

        CT_DrawParam result = resourceManage.superDrawParam(current, null);

        assertNotNull(result);
        assertNotSame(current, result);
        assertEquals(current.attributeValue("LineWidth"), result.attributeValue("LineWidth"));
    }

    @Test
    @DisplayName("the result is a defensive copy even when the parent has no Relative")
    void resultIsDefensiveCopy() {
        CT_DrawParam current = paramWithId(1L, null);
        current.setLineWidth(1.5);

        CT_DrawParam result = resourceManage.superDrawParam(current, new ArrayList<>());
        result.addAttribute("LineWidth", "999");

        assertNotSame(current, result);
        assertEquals("1.5", current.attributeValue("LineWidth"));
        assertEquals("999", result.attributeValue("LineWidth"));
    }

    // ---------------------------------------------------------------------
    // parent resolution
    // ---------------------------------------------------------------------

    @Test
    @DisplayName("missing parent leaves the copy unchanged")
    void missingParentLeavesCopyUnchanged() {
        CT_DrawParam current = paramWithId(1L, 999L);
        List<String> visited = new ArrayList<>();

        CT_DrawParam result = resourceManage.superDrawParam(current, visited);

        assertNotNull(result);
        assertNotSame(current, result);
        assertNull(result.attributeValue("LineWidth"));
        assertNull(result.getFillColor());
        assertNull(result.getStrokeColor());
        assertTrue(visited.isEmpty());
    }

    @Test
    @DisplayName("all missing drawing attributes are inherited from the direct parent")
    void inheritsAllAttributesFromDirectParent() {
        CT_DrawParam parent = registerParam(10L, null);
        fillWithAllAttributes(parent);

        CT_DrawParam current = paramWithId(20L, 10L);

        CT_DrawParam result = resourceManage.superDrawParam(current, new ArrayList<>());

        assertNotSame(current, result);
        assertEquals(10L, result.getRelative().getRefId().getId().longValue());
        assertHasAllAttributesOf(parent, result);
    }

    @Test
    @DisplayName("attributes already present on the current node are not overwritten")
    void existingAttributesAreNotOverwritten() {
        CT_DrawParam parent = registerParam(10L, null);
        fillWithAllAttributes(parent);

        CT_DrawParam current = paramWithId(20L, 10L);
        current.setLineWidth(0.5);
        current.setJoin(LineJoinType.Round);
        current.setCap(LineCapType.Square);
        current.setDashOffset(0.125);
        current.setDashPattern(new ST_Array(9d, 8d));
        current.setMiterLimit(1.5);
        current.setFillColor(CT_Color.rgb(1, 2, 3));
        current.setStrokeColor(CT_Color.rgb(4, 5, 6));

        Map<String, String> expected = new HashMap<>();
        expected.put("LineWidth", current.attributeValue("LineWidth"));
        expected.put("Join", current.attributeValue("Join"));
        expected.put("Cap", current.attributeValue("Cap"));
        expected.put("DashOffset", current.attributeValue("DashOffset"));
        expected.put("DashPattern", current.attributeValue("DashPattern"));
        expected.put("MiterLimit", current.attributeValue("MiterLimit"));
        String expectedFill = current.getFillColor().attributeValue("Value");
        String expectedStroke = current.getStrokeColor().attributeValue("Value");

        CT_DrawParam result = resourceManage.superDrawParam(current, new ArrayList<>());

        assertEquals(expected.get("LineWidth"), result.attributeValue("LineWidth"));
        assertEquals(expected.get("Join"), result.attributeValue("Join"));
        assertEquals(expected.get("Cap"), result.attributeValue("Cap"));
        assertEquals(expected.get("DashOffset"), result.attributeValue("DashOffset"));
        assertEquals(expected.get("DashPattern"), result.attributeValue("DashPattern"));
        assertEquals(expected.get("MiterLimit"), result.attributeValue("MiterLimit"));
        assertEquals(expectedFill, result.getFillColor().attributeValue("Value"));
        assertEquals(expectedStroke, result.getStrokeColor().attributeValue("Value"));
    }

    @Test
    @DisplayName("only the missing attributes are inherited while existing ones are preserved")
    void partiallyInheritsOnlyMissingAttributes() {
        CT_DrawParam parent = registerParam(10L, null);
        fillWithAllAttributes(parent);

        CT_DrawParam current = paramWithId(20L, 10L);
        current.setLineWidth(0.75);
        current.setFillColor(CT_Color.rgb(200, 100, 50));

        CT_DrawParam result = resourceManage.superDrawParam(current, new ArrayList<>());

        // preserved own values
        assertEquals(current.attributeValue("LineWidth"), result.attributeValue("LineWidth"));
        assertEquals("200 100 50", result.getFillColor().attributeValue("Value"));
        // inherited values
        assertEquals(parent.attributeValue("Join"), result.attributeValue("Join"));
        assertEquals(parent.attributeValue("Cap"), result.attributeValue("Cap"));
        assertEquals(parent.attributeValue("DashOffset"), result.attributeValue("DashOffset"));
        assertEquals(parent.attributeValue("DashPattern"), result.attributeValue("DashPattern"));
        assertEquals(parent.attributeValue("MiterLimit"), result.attributeValue("MiterLimit"));
        assertEquals(parent.getStrokeColor().attributeValue("Value"),
                result.getStrokeColor().attributeValue("Value"));
    }

    @Test
    @DisplayName("attributes are inherited through a chain of parents")
    void inheritsAttributesThroughParentChain() {
        CT_DrawParam grandParent = registerParam(30L, null);
        fillWithAllAttributes(grandParent);

        CT_DrawParam parent = registerParam(20L, 30L);
        CT_DrawParam current = paramWithId(10L, 20L);

        CT_DrawParam result = resourceManage.superDrawParam(current, new ArrayList<>());

        assertHasAllAttributesOf(grandParent, result);
        // the original resource objects must not be polluted by the resolution
        assertNull(parent.attributeValue("LineWidth"));
        assertNull(current.attributeValue("LineWidth"));
        assertNull(drawParamMap.get("20").attributeValue("LineWidth"));
    }

    @Test
    @DisplayName("when an intermediate parent is missing, the nearest available parent is used")
    void usesNearestAvailableParentWhenIntermediateMissing() {
        CT_DrawParam parent = registerParam(20L, 999L);
        parent.setLineWidth(6.5);
        parent.setJoin(LineJoinType.Round);

        CT_DrawParam current = paramWithId(10L, 20L);

        CT_DrawParam result = resourceManage.superDrawParam(current, new ArrayList<>());

        assertEquals(parent.attributeValue("LineWidth"), result.attributeValue("LineWidth"));
