        expected.put("LineWidth", current.attributeValue("LineWidth"));
        expected.put("Join", current.attributeValue("Join"));
        expected.put("Cap", current.attributeValue("Cap"));
        expected.put("DashOffset", current.attributeValue("DashOffset"));
        expected.put("DashPattern", current.attributeValue("DashPattern"));
