package org.ofdrw.sign.stamppos;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import org.ofdrw.core.basicType.ST_Box;
import org.ofdrw.core.signatures.appearance.StampAnnot;
import org.ofdrw.reader.OFDReader;
import org.ofdrw.sign.SignIDProvider;

import java.io.IOException;
import java.io.OutputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.regex.Matcher;
import java.util.zip.ZipEntry;
import java.util.zip.ZipOutputStream;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * 针对 {@link CuttingRideStampPos#getAppearance(OFDReader, SignIDProvider)} 的单元测试。
 * <p>
 * 测试通过运行时构造的最小 OFD 容器（真实 {@link OFDReader}）来提供页码、页面大小与页面对象 ID，
 * 不依赖任何外部资源文件。
 */
public class CuttingRideStampPosGetAppearanceTests {

    // ---------- 辅助：构造最小可解析 OFD 文档 ----------

    private static final String NS = "http://www.ofdspec.org/2016";

    /**
     * 文档级别默认页面大小，用于页面自身没有 Area 的场景
     */
    private static final double DEFAULT_DOC_WIDTH = 300d;
    private static final double DEFAULT_DOC_HEIGHT = 400d;

    /**
     * 页面对象ID：第 n 页（从0开始）的ID为 (n+1)*7，便于验证 PageRef 与页码一一对应
     */
    private static String pageObjectId(int pageIndex) {
        return String.valueOf((pageIndex + 1) * 7);
    }

    /**
     * 构造 OFD 文档
     *
     * @param dir       临时目录
     * @param pageSizes 每页的 {宽, 高}，元素为 null 表示该页不定义 Area（使用文档默认页面大小）
     * @return OFD 文件路径
     */
    private static Path buildOfd(Path dir, double[]... pageSizes) throws IOException {
        Path ofdFile = dir.resolve("ride-stamp.ofd");
        try (OutputStream os = Files.newOutputStream(ofdFile);
             ZipOutputStream zos = new ZipOutputStream(os)) {
            putEntry(zos, "OFD.xml", ofdXml());
            putEntry(zos, "Doc_0/Document.xml", documentXml(pageSizes.length));
            for (int i = 0; i < pageSizes.length; i++) {
                putEntry(zos, "Doc_0/Pages/Page_" + i + "/Content.xml", contentXml(pageSizes[i]));
            }
        }
        return ofdFile;
    }

    private static void putEntry(ZipOutputStream zos, String name, String content) throws IOException {
        zos.putNextEntry(new ZipEntry(name));
        zos.write(content.getBytes(StandardCharsets.UTF_8));
        zos.closeEntry();
    }

    private static String ofdXml() {
        return "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n"
                + "<ofd:OFD xmlns:ofd=\"" + NS + "\" Version=\"1.0\" DocType=\"OFD\">"
                + "<ofd:DocBody>"
                + "<ofd:DocInfo><ofd:DocID>1234567890</ofd:DocID>"
                + "<ofd:CreationDate>2020-09-21</ofd:CreationDate>"
                + "<ofd:Creator>unit test</ofd:Creator></ofd:DocInfo>"
                + "<ofd:DocRoot>Doc_0/Document.xml</ofd:DocRoot>"
                + "</ofd:DocBody></ofd:OFD>";
    }

    private static String documentXml(int numPage) {
        StringBuilder sb = new StringBuilder();
        sb.append("<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n")
                .append("<ofd:Document xmlns:ofd=\"").append(NS).append("\">")
                .append("<ofd:CommonData>")
                .append("<ofd:PageArea><ofd:PhysicalBox>0 0 ")
                .append(fmt(DEFAULT_DOC_WIDTH)).append(' ').append(fmt(DEFAULT_DOC_HEIGHT))
                .append("</ofd:PhysicalBox></ofd:PageArea>")
                .append("<ofd:MaxUnitID>100</ofd:MaxUnitID>")
                .append("</ofd:CommonData>")
                .append("<ofd:Pages>");
        for (int i = 0; i < numPage; i++) {
            sb.append("<ofd:Page ID=\"").append(pageObjectId(i))
                    .append("\" BaseLoc=\"Pages/Page_").append(i).append("/Content.xml\"/>");
        }
        sb.append("</ofd:Pages></ofd:Document>");
        return sb.toString();
    }

    private static String contentXml(double[] pageSize) {
        StringBuilder sb = new StringBuilder();
        sb.append("<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n")
                .append("<ofd:Page xmlns:ofd=\"").append(NS).append("\">");
        if (pageSize != null) {
            sb.append("<ofd:Area><ofd:PhysicalBox>0 0 ")
                    .append(fmt(pageSize[0])).append(' ').append(fmt(pageSize[1]))
                    .append("</ofd:PhysicalBox></ofd:Area>");
        }
        sb.append("<ofd:Content><ofd:Layer ID=\"1\"><ofd:TextObject ID=\"2\" Boundary=\"0 0 10 10\" Font=\"3\" Size=\"3.0\">")
                .append("t</ofd:TextObject></ofd:Layer></ofd:Content>");
        sb.append("</ofd:Page>");
        return sb.toString();
    }

    private static String fmt(double value) {
        if (value == (long) value) {
            return String.valueOf((long) value);
        }
        return String.valueOf(value);
    }

    /**
     * 生成 n 页且每页大小一致的文档
     */
    private static Path buildOfd(Path dir, int numPage, double pageWidth, double pageHeight) throws IOException {
        double[][] sizes = new double[numPage][];
        for (int i = 0; i < numPage; i++) {
            sizes[i] = new double[]{pageWidth, pageHeight};
        }
        return buildOfd(dir, sizes);
    }

    /**
     * 简单自增 ID 提供器，格式 sNNN，从 1 开始
     */
    private static final class CountingIDProvider implements SignIDProvider {
        private int current = 0;

        @Override
        public void setCurrentMaxSignId(String maxSignId) {
            if (maxSignId == null) {
                current = 0;
                return;
            }
            Matcher m = IDPattern.matcher(maxSignId);
            current = m.matches() ? Integer.parseInt(m.group(1)) : 0;
        }

        @Override
        public String incrementAndGet() {
            current += 1;
            return String.format("s%03d", current);
        }

        @Override
        public String get() {
            return String.format("s%03d", current);
        }

        @Override
        public int parse(String id) {
            Matcher m = IDPattern.matcher(id == null ? "" : id);
            if (!m.matches()) {
                throw new NumberFormatException("非法签名ID: " + id);
            }
            return Integer.parseInt(m.group(1));
        }
    }

    private static CuttingRatio ratio(double left, double right) {
        CuttingRatio r = new CuttingRatio();
        r.setLeft(left);
        r.setRight(right);
        return r;
    }

    // ---------- 辅助：断言 ----------

    private static void assertBoundary(StampAnnot annot, double x, double y, double w, double h) {
        ST_Box boundary = annot.getBoundary();
        assertNotNull(boundary, "Boundary 不应为空");
        assertEquals(x, boundary.getTopLeftX(), 1e-6, "Boundary.X");
        assertEquals(y, boundary.getTopLeftY(), 1e-6, "Boundary.Y");
        assertEquals(w, boundary.getWidth(), 1e-6, "Boundary.Width");
        assertEquals(h, boundary.getHeight(), 1e-6, "Boundary.Height");
    }

    private static void assertClip(StampAnnot annot, double x, double y, double w, double h) {
        ST_Box clip = annot.getClip();
        assertNotNull(clip, "Clip 不应为空");
        assertEquals(x, clip.getTopLeftX(), 1e-6, "Clip.X");
        assertEquals(y, clip.getTopLeftY(), 1e-6, "Clip.Y");
        assertEquals(w, clip.getWidth(), 1e-6, "Clip.Width");
        assertEquals(h, clip.getHeight(), 1e-6, "Clip.Height");
    }

    private static void assertNoClip(StampAnnot annot) {
        assertNull(annot.getClip(), "Clip 应为空");
