                    .append("\" BaseLoc=\"Pages/Page_").append(i).append("/Content.xml\"/>");
        }
        sb.append("</ofd:Pages></ofd:Document>");
        return sb.toString();
    }

    private static String contentXml(double[] pageSize) {
        StringBuilder sb = new StringBuilder();
        sb.append("<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n")
                .append("<ofd:Page xmlns:ofd=\"").append(NS).append("\">");
        if (pageSize != null) {
            sb.append("<ofd:Area><ofd:PhysicalBox>0 0 ")
                    .append(fmt(pageSize[0])).append(' ').append(fmt(pageSize[1]))
                    .append("</ofd:PhysicalBox></ofd:Area>");
        }
        sb.append("<ofd:Content><ofd:Layer ID=\"1\"><ofd:TextObject ID=\"2\" Boundary=\"0 0 10 10\" Font=\"3\" Size=\"3.0\">")
                .append("t</ofd:TextObject></ofd:Layer></ofd:Content>");
        sb.append("</ofd:Page>");
        return sb.toString();
    }

    private static String fmt(double value) {
        if (value == (long) value) {
            return String.valueOf((long) value);
        }
        return String.valueOf(value);
    }

    /**
     * 生成 n 页且每页大小一致的文档
     */
    private static Path buildOfd(Path dir, int numPage, double pageWidth, double pageHeight) throws IOException {
        double[][] sizes = new double[numPage][];
        for (int i = 0; i < numPage; i++) {
            sizes[i] = new double[]{pageWidth, pageHeight};
        }
        return buildOfd(dir, sizes);
    }

    /**
     * 简单自增 ID 提供器，格式 sNNN，从 1 开始
     */
    private static final class CountingIDProvider implements SignIDProvider {
        private int current = 0;

        @Override
        public void setCurrentMaxSignId(String maxSignId) {
            if (maxSignId == null) {
                current = 0;
                return;
            }
            Matcher m = IDPattern.matcher(maxSignId);
            current = m.matches() ? Integer.parseInt(m.group(1)) : 0;
        }

        @Override
        public String incrementAndGet() {
            current += 1;
            return String.format("s%03d", current);
        }

        @Override
        public String get() {
            return String.format("s%03d", current);
        }

        @Override
        public int parse(String id) {
            Matcher m = IDPattern.matcher(id == null ? "" : id);
            if (!m.matches()) {
                throw new NumberFormatException("非法签名ID: " + id);
            }
            return Integer.parseInt(m.group(1));
        }
    }

    private static CuttingRatio ratio(double left, double right) {
        CuttingRatio r = new CuttingRatio();
        r.setLeft(left);
        r.setRight(right);
        return r;
    }

