        return this;
    }

    public Double getWidth() {
        return width;
    }

    public ST_Box setWidth(Double width) {
        this.width = width;
        return this;
    }

    public Double getHeight() {
        return height;
    }

    public ST_Box setHeight(Double height) {
        this.height = height;
        return this;
    }

