            if (fileChanged(filename, element)) {
                ElemCup.dumpUpNS(element, filePath);
            }
        }
        // 递归的刷新容器中包含的其他容器
        for (VirtualContainer container : dirCache.values()) {
            container.flush();
        }
        fileCache.clear();
        dirCache.clear();
    }

